select @FromDate AS DocumentDate, 'Opening' AS DocumentType,'' as CostCenterName, TABopening.CustomerID, TABopening.CustomerName,null as DocumentNo, Abs(Sum(Debit)) debit,
Sum(credit) as credit,'' as InstrumentNo,'' as Comments,CodeCombinationID CodeCombinationID,CodeDescription
from ( SELECT 'Opening' as DocumentType, FinTab.DocumentDate, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, '' As InstrumentNo, FinTab.Comments, FinTab.CodeCombinationID ,FinTab.CodeDescription FROM ( Select distinct OpeningTAB.DocumentDate, OpeningTAB.DocumentType, OpeningTAB.CostCenterName, OpeningTAB.CustomerID, OpeningTAB.CustomerName, OpeningTAB.DocumentNo, Sum(OpeningTAB.Debit) As Debit, Sum(OpeningTAB.Credit) As Credit, '' As InstrumentNo, OpeningTAB.Description As Comments, OpeningTAB.CodeCombinationID ,OpeningTAB.CodeDescription From ( --------------- Sale Invice Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, Sal_InvoiceHeader.Description, GL_TransactionDetail.CodeCombinationID, Case When GL_TransactionDetail.TransactionType = 'Debit' Then GL_TransactionDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then GL_TransactionDetail.Amount Else 0 End As Credit ,GL_codecombinationDetail.Description as CodeDescription From GL_TransactionHeader Inner Join GL_TransactionDetail On GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID And GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID And GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID And GL_TransactionDetail.Status = 1 And GL_TransactionDetail.TransactionType = 'Debit' Inner Join Sal_InvoiceHeader On Sal_InvoiceHeader.CompanyID = GL_TransactionHeader.CompanyID And Sal_InvoiceHeader.PeriodID = GL_TransactionHeader.PeriodID And Sal_InvoiceHeader.InvoiceType = GL_TransactionHeader.DocumentTypeID And Sal_InvoiceHeader.InvoiceNumber = GL_TransactionHeader.DocumentNo And Sal_InvoiceHeader.Status = 1 And Sal_InvoiceHeader.StatusCode = 1 and Sal_InvoiceHeader.FiscalID = GL_TransactionHeader.FiscalID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = GL_TransactionHeader.CompanyID And Set_DocumentType.PeriodID = GL_TransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And Set_DocumentType.IsActive = 1 And Set_DocumentType.Status = 1 Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = Sal_InvoiceHeader.PeriodID --AR_Set_Customer.CompanyID = Sal_InvoiceHeader.CompanyID And And AR_Set_Customer.CustomerID = Sal_InvoiceHeader.CustomerID And AR_Set_Customer.IsActive = 1 And AR_Set_Customer.Status = 1 Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID
Where GL_TransactionHeader.CompanyID = @CompanyID and GL_TransactionHeader.PeriodID = @PeriodID and GL_TransactionHeader.ReversalID is null and GL_TransactionHeader.ReversalDate is null and isnull(GL_TransactionHeader.IsReversed,0) = 0 AND GL_TransactionHeader.DocumentDate < @FromDate and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0}
) As OpeningTAB Group By OpeningTAB.DocumentDate, OpeningTAB.DocumentType, OpeningTAB.CostCenterName, OpeningTAB.CustomerID, OpeningTAB.CustomerName, OpeningTAB.DocumentNo, OpeningTAB.Description, OpeningTAB.CodeCombinationID ,OpeningTAB.CodeDescription
UNION ALL ---------- Sales Invoice Customer Detail ---------- Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, '' As InstrumentNo, FinTab.Narration As Comments, FinTab.CustomerAccountCode As CodeCombinationID ,FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, Sal_InvoiceCustomerDetail.Narration, Sal_InvoiceCustomerDetail.CustomerAccountCode, Case When GL_TransactionDetail.TransactionType = 'Debit' Then Sal_InvoiceCustomerDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then Sal_InvoiceCustomerDetail.Amount Else 0 End As Credit ,GL_codecombinationDetail.Description as CodeDescription From GL_TransactionHeader Inner Join GL_TransactionDetail On GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID And GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID And GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID And GL_TransactionDetail.Status = 1 Inner Join Sal_InvoiceHeader On Sal_InvoiceHeader.CompanyID = GL_TransactionHeader.CompanyID And Sal_InvoiceHeader.PeriodID = GL_TransactionHeader.PeriodID And Sal_InvoiceHeader.InvoiceType = GL_TransactionHeader.DocumentTypeID And Sal_InvoiceHeader.InvoiceNumber = GL_TransactionHeader.DocumentNo And Sal_InvoiceHeader.Status = 1 And Sal_InvoiceHeader.StatusCode = 1 and Sal_InvoiceHeader.FiscalID = GL_TransactionHeader.FiscalID Inner Join Sal_InvoiceCustomerDetail On Sal_InvoiceCustomerDetail.CompanyID = Sal_InvoiceHeader.CompanyID And Sal_InvoiceCustomerDetail.PeriodID = Sal_InvoiceHeader.PeriodID And Sal_InvoiceCustomerDetail.InvoiceHeaderID = Sal_InvoiceHeader.InvoiceID And Sal_InvoiceCustomerDetail.CustomerAccountCode = GL_TransactionDetail.CodeCombinationID And Sal_InvoiceCustomerDetail.TransactionType = GL_TransactionDetail.TransactionType Inner Join Set_DocumentType On Set_DocumentType.CompanyID = GL_TransactionHeader.CompanyID And Set_DocumentType.PeriodID = GL_TransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And Set_DocumentType.IsActive = 1 And Set_DocumentType.Status = 1 Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = Sal_InvoiceCustomerDetail.PeriodID And AR_Set_Customer.CustomerID = Sal_InvoiceCustomerDetail.CustomerID And AR_Set_Customer.IsActive = 1 And AR_Set_Customer.Status = 1 Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID Where GL_TransactionHeader.CompanyID = @CompanyID and GL_TransactionHeader.PeriodID = @PeriodID --And IsNull(Sal_InvoiceHeader.IsReversed, 0) = 0 And Sal_InvoiceHeader.ReversalID is null {5} AND GL_TransactionHeader.DocumentDate < @FromDate and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0}
) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.Narration, FinTab.CustomerAccountCode ,FinTab.CodeDescription
Union All
---------- Sales Receipt Customer Detail ---------- Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, FinTab.PaymentServerOrderNo As InstrumentNo, FinTab.Narration As Comments, FinTab.CustomerAccountCode As CodeCombinationID ,FinTab.CodeDescription From ( Select DISTINCT GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.PaymentServerOrderNo, AR_ReceiptCustomerDetail.Narration, AR_ReceiptCustomerDetail.CustomerAccountCode, Case When GL_TransactionDetail.TransactionType = 'Debit' Then AR_ReceiptCustomerDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then AR_ReceiptCustomerDetail.Amount Else 0 End As Credit ,GL_codecombinationDetail.Description as CodeDescription ,AR_ReceiptCustomerDetail.ReceiptCustomerID From GL_TransactionHeader Inner Join GL_TransactionDetail On GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID And GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID And GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID And GL_TransactionDetail.Status = 1 Inner Join AR_ReceiptTransactionHeader On AR_ReceiptTransactionHeader.CompanyID = GL_TransactionHeader.CompanyID And AR_ReceiptTransactionHeader.PeriodID = GL_TransactionHeader.PeriodID And AR_ReceiptTransactionHeader.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And AR_ReceiptTransactionHeader.DocumentNo = GL_TransactionHeader.DocumentNo And AR_ReceiptTransactionHeader.Status = 1 And AR_ReceiptTransactionHeader.StatusCode = 1 and AR_ReceiptTransactionHeader.FiscalID = GL_TransactionHeader.FiscalID Inner Join AR_ReceiptCustomerDetail On AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID And AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID And AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID And AR_ReceiptCustomerDetail.CustomerAccountCode = GL_TransactionDetail.CodeCombinationID And AR_ReceiptCustomerDetail.TransactionType = GL_TransactionDetail.TransactionType Inner Join Set_DocumentType On Set_DocumentType.CompanyID = GL_TransactionHeader.CompanyID And Set_DocumentType.PeriodID = GL_TransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And Set_DocumentType.IsActive = 1 And Set_DocumentType.Status = 1 Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = AR_ReceiptCustomerDetail.PeriodID And AR_Set_Customer.CustomerID = AR_ReceiptCustomerDetail.CustomerID And AR_Set_Customer.IsActive = 1 And AR_Set_Customer.Status = 1 Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID Where GL_TransactionHeader.CompanyID = @CompanyID and GL_TransactionHeader.PeriodID = @PeriodID --And AR_ReceiptTransactionHeader.ReversalComments is null {6} AND GL_TransactionHeader.DocumentDate < @FromDate and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0}
) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.PaymentServerOrderNo, FinTab.Narration, FinTab.CustomerAccountCode ,FinTab.CodeDescription
Union All
---------- Purchase Invoice Header ---------- Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, '' As InstrumentNo, FinTab.Description As Comments, FinTab.CodeCombinationID ,FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AR_InvoiceHeader.Description, GL_TransactionDetail.CodeCombinationID, Case When GL_TransactionDetail.TransactionType = 'Debit' Then GL_TransactionDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then GL_TransactionDetail.Amount Else 0 End As Credit ,GL_codecombinationDetail.Description as CodeDescription From GL_TransactionHeader Inner Join GL_TransactionDetail On GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID And GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID And GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID And GL_TransactionDetail.Status = 1 Inner Join AR_InvoiceHeader On AR_InvoiceHeader.CompanyID = GL_TransactionHeader.CompanyID And AR_InvoiceHeader.PeriodID = GL_TransactionHeader.PeriodID And AR_InvoiceHeader.InvoiceType = GL_TransactionHeader.DocumentTypeID And AR_InvoiceHeader.InvoiceNumber = GL_TransactionHeader.DocumentNo And AR_InvoiceHeader.Status = 1 And AR_InvoiceHeader.StatusCode = 1 and AR_InvoiceHeader.FiscalID = GL_TransactionHeader.FiscalID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = GL_TransactionHeader.CompanyID And Set_DocumentType.PeriodID = GL_TransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And Set_DocumentType.IsActive = 1 And Set_DocumentType.Status = 1 Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = AR_InvoiceHeader.PeriodID And AR_Set_Customer.CustomerID = AR_InvoiceHeader.VendorID And AR_Set_Customer.IsActive = 1 And AR_Set_Customer.Status = 1 Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID Inner Join AR_SET_BusinessPartnerTypes On AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceHeader.CompanyID And AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID And AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.VendorID And AR_SET_BusinessPartnerTypes.TypeCode = AR_InvoiceHeader.BusinessPartnerTypeID And AR_SET_BusinessPartnerTypes.FK_CodeCombinationID = GL_TransactionDetail.CodeCombinationID Where GL_TransactionHeader.CompanyID = @CompanyID and GL_TransactionHeader.PeriodID = @PeriodID -- and GL_TransactionDetail.TransactionType = 'Credit' AND (dbo.GL_TransactionDetail.CodeCombinationID In (SELECT Distinct DefaultAccountCode FROM dbo.SET_DocumentType WHERE (DocumentType Like 'Advance Against PO%') AND (CompanyID = @CompanyID) AND (PeriodID = @PeriodID))) AND (dbo.GL_TransactionDetail.TransactionType = 'Credit') and AR_InvoiceHeader.IsReversed is null and AR_InvoiceHeader.ReversalID is null and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) AND GL_TransactionHeader.DocumentDate < @FromDate {0}
) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.Description, FinTab.CodeCombinationID ,FinTab.CodeDescription UNION ALL ---------- Purchase Advance KnokOff ---------- Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, '' As InstrumentNo, FinTab.Description As Comments, FinTab.CodeCombinationID ,FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AR_InvoiceHeader.Description, AR_SET_BusinessPartnerTypes.FK_CodeCombinationID AS CodeCombinationID, Case When GL_TransactionDetail.TransactionType = 'Credit' Then GL_TransactionDetail.Amount Else 0 End As Debit, 0 As Credit ,GL_codecombinationDetail.Description as CodeDescription From GL_TransactionHeader
Inner Join GL_TransactionDetail On GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID And GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID And GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID And GL_TransactionDetail.Status = 1 Inner Join AR_InvoiceHeader On AR_InvoiceHeader.CompanyID = GL_TransactionHeader.CompanyID And AR_InvoiceHeader.PeriodID = GL_TransactionHeader.PeriodID And AR_InvoiceHeader.InvoiceType = GL_TransactionHeader.DocumentTypeID And AR_InvoiceHeader.InvoiceNumber = GL_TransactionHeader.DocumentNo And AR_InvoiceHeader.Status = 1 And AR_InvoiceHeader.StatusCode = 1 and AR_InvoiceHeader.FiscalID = GL_TransactionHeader.FiscalID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = GL_TransactionHeader.CompanyID And Set_DocumentType.PeriodID = GL_TransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And Set_DocumentType.IsActive = 1 And Set_DocumentType.Status = 1 Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = AR_InvoiceHeader.PeriodID And AR_Set_Customer.CustomerID = AR_InvoiceHeader.VendorID And AR_Set_Customer.IsActive = 1 And AR_Set_Customer.Status = 1 left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.VendorID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = 1 LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = AR_SET_BusinessPartnerTypes.FK_CodeCombinationID Where GL_TransactionHeader.CompanyID = @CompanyID and GL_TransactionHeader.PeriodID = @PeriodID and AR_InvoiceHeader.IsReversed is null and AR_InvoiceHeader.ReversalID is null AND GL_TransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate and GL_TransactionDetail.codecombinationID in (SELECT Distinct DefaultAccountCode FROM SET_DocumentType WHERE DocumentType like 'Advance Against PO%' AND CompanyID = @CompanyID AND PeriodID = @PeriodID) AND GL_TransactionHeader.DocumentDate < @FromDate and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.Description, FinTab.CodeCombinationID, FinTab.CodeDescription
union all ---------- Purchase Advance KnokOff ---------- Copy 2 Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, '' As InstrumentNo, FinTab.Description As Comments, FinTab.CodeCombinationID ,FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AR_InvoiceHeader.Description, AR_SET_BusinessPartnerTypes.FK_CodeCombinationID AS CodeCombinationID, 0 As Debit, GL_TransactionDetail.Amount As Credit ,GL_codecombinationDetail.Description as CodeDescription From GL_TransactionHeader
Inner Join GL_TransactionDetail On GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID And GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID And GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID And GL_TransactionDetail.Status = 1 Inner Join AR_InvoiceHeader On AR_InvoiceHeader.CompanyID = GL_TransactionHeader.CompanyID And AR_InvoiceHeader.PeriodID = GL_TransactionHeader.PeriodID And AR_InvoiceHeader.InvoiceType = GL_TransactionHeader.DocumentTypeID And AR_InvoiceHeader.InvoiceNumber = GL_TransactionHeader.DocumentNo And AR_InvoiceHeader.Status = 1 And AR_InvoiceHeader.StatusCode = 1 and AR_InvoiceHeader.FiscalID = GL_TransactionHeader.FiscalID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = GL_TransactionHeader.CompanyID And Set_DocumentType.PeriodID = GL_TransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And Set_DocumentType.IsActive = 1 And Set_DocumentType.Status = 1 Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = AR_InvoiceHeader.PeriodID And AR_Set_Customer.CustomerID = AR_InvoiceHeader.VendorID And AR_Set_Customer.IsActive = 1 And AR_Set_Customer.Status = 1 left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.VendorID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = 1 LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = AR_SET_BusinessPartnerTypes.FK_CodeCombinationID Where GL_TransactionHeader.CompanyID = @CompanyID and GL_TransactionHeader.PeriodID = @PeriodID and AR_InvoiceHeader.IsReversed is null and AR_InvoiceHeader.ReversalID is null AND GL_TransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate and GL_TransactionDetail.codecombinationID in (SELECT Distinct DefaultAccountCode FROM SET_DocumentType WHERE DocumentType like 'Advance Against PO%' AND CompanyID = @CompanyID AND PeriodID = @PeriodID) AND GL_TransactionHeader.DocumentDate < @FromDate and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.Description, FinTab.CodeCombinationID, FinTab.CodeDescription
Union All
Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, '' As InstrumentNo, FinTab.Narration As Comments, FinTab.SupplierAccountCode As CodeCombinationID ,FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AR_InvoiceSupplierDetail.SupplierAccountCode, AR_InvoiceSupplierDetail.Narration, Case When GL_TransactionDetail.TransactionType = 'Debit' Then AR_InvoiceSupplierDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then AR_InvoiceSupplierDetail.Amount Else 0 End As Credit ,GL_codecombinationDetail.Description as CodeDescription, AR_InvoiceSupplierDetail.InvoiceSupplierID From GL_TransactionHeader Inner Join GL_TransactionDetail On GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID And GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID And GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID And GL_TransactionDetail.Status = 1 Inner Join AR_InvoiceHeader On AR_InvoiceHeader.CompanyID = GL_TransactionHeader.CompanyID And AR_InvoiceHeader.PeriodID = GL_TransactionHeader.PeriodID And AR_InvoiceHeader.InvoiceType = GL_TransactionHeader.DocumentTypeID And AR_InvoiceHeader.InvoiceNumber = GL_TransactionHeader.DocumentNo And AR_InvoiceHeader.Status = 1 And AR_InvoiceHeader.StatusCode = 1 and AR_InvoiceHeader.FiscalID = GL_TransactionHeader.FiscalID Inner Join AR_InvoiceSupplierDetail On AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID And AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID And AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID And AR_InvoiceSupplierDetail.SupplierAccountCode = GL_TransactionDetail.CodeCombinationID And AR_InvoiceSupplierDetail.TransactionType = GL_TransactionDetail.TransactionType Inner Join Set_DocumentType On Set_DocumentType.CompanyID = GL_TransactionHeader.CompanyID And Set_DocumentType.PeriodID = GL_TransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And Set_DocumentType.IsActive = 1 And Set_DocumentType.Status = 1 Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = AR_InvoiceSupplierDetail.PeriodID And AR_Set_Customer.CustomerID = AR_InvoiceSupplierDetail.SupplierID And AR_Set_Customer.IsActive = 1 And AR_Set_Customer.Status = 1 Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID Where GL_TransactionHeader.CompanyID = @CompanyID and GL_TransactionHeader.PeriodID = @PeriodID --And IsNull(AR_InvoiceHeader.IsReversed, 0) = 0 And AR_InvoiceHeader.ReversalID is null {7} AND GL_TransactionHeader.DocumentDate < @FromDate and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {2} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.Narration, FinTab.SupplierAccountCode ,FinTab.CodeDescription Union All ---------- Payment Supplier Detail ---------- Select FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, FinTab.PaymentServerOrderNo As InstrumentNo, Fintab.Narration As Comments, FinTab.SupplierAccountCode As CodeCombinationID ,FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AP_PaymentHeader.PaymentServerOrderNo, AP_PaymentSupplierDetail.Narration, AP_PaymentSupplierDetail.SupplierAccountCode, Case When GL_TransactionDetail.TransactionType = 'Debit' Then AP_PaymentSupplierDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then AP_PaymentSupplierDetail.Amount Else 0 End As Credit ,GL_codecombinationDetail.Description as CodeDescription ,AP_PaymentSupplierDetail.PaymentSupplierID From GL_TransactionHeader Inner Join GL_TransactionDetail On GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID And GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID And GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID And GL_TransactionDetail.Status = 1 Inner Join AP_PaymentHeader On AP_PaymentHeader.CompanyID = GL_TransactionHeader.CompanyID And AP_PaymentHeader.PeriodID = GL_TransactionHeader.PeriodID And AP_PaymentHeader.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And AP_PaymentHeader.DocumentNo = GL_TransactionHeader.DocumentNo And AP_PaymentHeader.Status = 1 And AP_PaymentHeader.StatusCode = 1 and AP_PaymentHeader.FiscalID = GL_TransactionHeader.FiscalID Inner Join AP_PaymentSupplierDetail On AP_PaymentSupplierDetail.CompanyID = AP_PaymentHeader.CompanyID And AP_PaymentSupplierDetail.PeriodID = AP_PaymentHeader.PeriodID And AP_PaymentSupplierDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID And AP_PaymentSupplierDetail.SupplierAccountCode = GL_TransactionDetail.CodeCombinationID And AP_PaymentSupplierDetail.TransactionType = GL_TransactionDetail.TransactionType Inner Join Set_DocumentType On Set_DocumentType.CompanyID = GL_TransactionHeader.CompanyID And Set_DocumentType.PeriodID = GL_TransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And Set_DocumentType.IsActive = 1 And Set_DocumentType.Status = 1 Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = AP_PaymentSupplierDetail.PeriodID And AR_Set_Customer.CustomerID = AP_PaymentSupplierDetail.SupplierID And AR_Set_Customer.IsActive = 1 And AR_Set_Customer.Status = 1 Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID Where GL_TransactionHeader.CompanyID = @CompanyID and GL_TransactionHeader.PeriodID = @PeriodID --And AP_PaymentHeader.ReversalComments is null {8} and Set_DocumentType.DocumentType not like 'Grower Loan Payment' AND GL_TransactionHeader.DocumentDate < @FromDate and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.PaymentServerOrderNo, Fintab.Narration, FinTab.SupplierAccountCode ,FinTab.CodeDescription
union all -- payment against vendor invoices Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, FinTab.PaymentServerOrderNo As InstrumentNo, Fintab.Narration As Comments, FinTab.SupplierAccountCode As CodeCombinationID ,FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AP_PaymentHeader.PaymentServerOrderNo, ' ' as Narration, GL_TransactionDetail.CodeCombinationID as SupplierAccountCode, Case When GL_TransactionDetail.TransactionType = 'Debit' Then GL_TransactionDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then GL_TransactionDetail.Amount Else 0 End As Credit ,GL_codecombinationDetail.Description as CodeDescription From GL_TransactionHeader Inner Join GL_TransactionDetail On GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID And GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID And GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID And GL_TransactionDetail.Status = 1 Inner Join AP_PaymentHeader On AP_PaymentHeader.CompanyID = GL_TransactionHeader.CompanyID And AP_PaymentHeader.PeriodID = GL_TransactionHeader.PeriodID And AP_PaymentHeader.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And AP_PaymentHeader.DocumentNo = GL_TransactionHeader.DocumentNo And AP_PaymentHeader.Status = 1 And AP_PaymentHeader.StatusCode = 1 and AP_PaymentHeader.FiscalID = GL_TransactionHeader.FiscalID inner join SET_DocumentType on SET_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID and SET_DocumentType.CompanyID = AP_PaymentHeader.CompanyID and SET_DocumentType.PeriodID = AP_PaymentHeader.PeriodID INNER JOIN SET_Bucket ON AP_PaymentHeader.CompanyID = SET_Bucket.CompanyID and SET_Bucket.Status = 1 and SET_Bucket.IsActive = 1 INNER JOIN AR_SET_Customer ON AP_PaymentHeader.VendorID = AR_SET_Customer.CustomerID --AND AP_PaymentHeader.CompanyID = AR_SET_Customer.CompanyID AND AP_PaymentHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = AR_Set_Customer.CustomerAccountCCID Where GL_TransactionHeader.CompanyID = @CompanyID and GL_TransactionHeader.PeriodID = @PeriodID and GL_TransactionDetail.TransactionType = 'Debit' --And AP_PaymentHeader.ReversalComments is null {8} and SET_DocumentType.DocumentType not like 'Advance Against PO%' AND GL_TransactionHeader.DocumentDate < @FromDate and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.PaymentServerOrderNo, Fintab.Narration, FinTab.SupplierAccountCode ,FinTab.CodeDescription
union all
----------- Advance Against PO
Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, FinTab.PaymentServerOrderNo As InstrumentNo, Fintab.Narration As Comments, FinTab.SupplierAccountCode As CodeCombinationID ,FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AP_PaymentHeader.PaymentServerOrderNo, ' ' as Narration, GL_TransactionDetail.CodeCombinationID as SupplierAccountCode, Case When GL_TransactionDetail.TransactionType = 'Debit' Then GL_TransactionDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then GL_TransactionDetail.Amount Else 0 End As Credit ,GL_codecombinationDetail.Description as CodeDescription FROM SET_DocumentType INNER JOIN AP_PaymentHeader ON SET_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND SET_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AP_PaymentHeader.documentTypeID AND AP_PaymentHeader .Status = 1 AND AP_PaymentHeader .StatusCode = 1
inner JOIN AR_SET_Customer ON AP_PaymentHeader.VendorID = AR_SET_Customer.CustomerID --AND AP_PaymentHeader.CompanyID = AR_SET_Customer.CompanyID AND AP_PaymentHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 inner join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = AP_PaymentHeader.documentNo and GL_TransactionHeader.DocumentTypeID = AP_PaymentHeader.DocumentTypeID and AP_PaymentHeader.FiscalID = GL_TransactionHeader.FiscalID INNER JOIN dbo.GL_TransactionDetail ON dbo.GL_TransactionHeader.TransactionID = dbo.GL_TransactionDetail.TransactionID AND dbo.GL_TransactionHeader.PeriodID = dbo.GL_TransactionDetail.PeriodID AND dbo.GL_TransactionHeader.CompanyID = dbo.GL_TransactionDetail.CompanyID
AND (dbo.GL_TransactionDetail.CodeCombinationID = (SELECT Max(DefaultAccountCode) FROM dbo.SET_DocumentType WHERE (DocumentType like 'Advance Against PO%') AND (CompanyID = @CompanyID) AND (PeriodID = @PeriodID) And DefaultAccountCode is not null)) AND (dbo.GL_TransactionDetail.TransactionType = 'Debit')
left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AP_PaymentHeader.VendorID AND AR_SET_BusinessPartnerTypes.CompanyID = AP_PaymentHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AP_PaymentHeader.PeriodID
LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = AR_Set_Customer.CustomerAccountCCID WHERE AP_PaymentHeader.CompanyID = @companyId AND AP_PaymentHeader.PeriodID = @PeriodId AND AP_PaymentHeader.DocumentDate < @FromDate --And AP_PaymentHeader.ReversalComments is null {8} AND (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.PaymentServerOrderNo, Fintab.Narration, FinTab.SupplierAccountCode ,FinTab.CodeDescription
union all
---------- Advance Against SO ---------- Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, FinTab.PaymentServerOrderNo As InstrumentNo, Fintab.Narration As Comments, FinTab.SupplierAccountCode As CodeCombinationID, FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.PaymentServerOrderNo, ' ' as Narration, GL_TransactionDetail.CodeCombinationID as SupplierAccountCode, Case When GL_TransactionDetail.TransactionType = 'Debit' Then GL_TransactionDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then GL_TransactionDetail.Amount Else 0 End As Credit, GL_codecombinationDetail.Description as CodeDescription FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 inner JOIN AR_SET_Customer ON AR_ReceiptTransactionHeader.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 inner join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = AR_ReceiptTransactionHeader.documentNo and GL_TransactionHeader.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID and AR_ReceiptTransactionHeader.FiscalID = GL_TransactionHeader.FiscalID INNER JOIN dbo.GL_TransactionDetail ON GL_TransactionHeader.TransactionID = GL_TransactionDetail.TransactionID AND GL_TransactionHeader.PeriodID = GL_TransactionDetail.PeriodID AND GL_TransactionHeader.CompanyID = GL_TransactionDetail.CompanyID AND GL_TransactionDetail.CodeCombinationID = ( SELECT max(DefaultAccountCode) FROM SET_DocumentType WHERE DocumentType like 'Advance Against SO%' AND CompanyID = @CompanyID AND PeriodID = @PeriodID And DefaultAccountCode is not null ) AND GL_TransactionDetail.TransactionType = 'Credit' left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_ReceiptTransactionHeader.CustomerID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_ReceiptTransactionHeader.PeriodID LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = AR_Set_Customer.CustomerAccountCCID WHERE AR_ReceiptTransactionHeader.CompanyID = @companyId AND AR_ReceiptTransactionHeader.PeriodID = @PeriodId AND AR_ReceiptTransactionHeader.DocumentDate < @FromDate --AND AR_ReceiptTransactionHeader.ReversalComments is null {6} AND (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.PaymentServerOrderNo, Fintab.Narration, FinTab.SupplierAccountCode, FinTab.CodeDescription
union all ---------- Receipt against Invoices - Loan Recovery ---------- Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, FinTab.PaymentServerOrderNo As InstrumentNo, Fintab.Narration As Comments, FinTab.SupplierAccountCode As CodeCombinationID, FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.PaymentServerOrderNo, ' ' as Narration, GL_TransactionDetail.CodeCombinationID as SupplierAccountCode, Case When GL_TransactionDetail.TransactionType = 'Debit' Then GL_TransactionDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then GL_TransactionDetail.Amount Else 0 End As Credit, GL_codecombinationDetail.Description as CodeDescription FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 inner JOIN AR_SET_Customer ON AR_ReceiptTransactionHeader.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 inner join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = AR_ReceiptTransactionHeader.documentNo and GL_TransactionHeader.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID and AR_ReceiptTransactionHeader.FiscalID = GL_TransactionHeader.FiscalID INNER JOIN dbo.GL_TransactionDetail ON GL_TransactionHeader.TransactionID = GL_TransactionDetail.TransactionID AND GL_TransactionHeader.PeriodID = GL_TransactionDetail.PeriodID AND GL_TransactionHeader.CompanyID = GL_TransactionDetail.CompanyID AND GL_TransactionDetail.TransactionType = 'Credit' Inner JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_ReceiptTransactionHeader.CustomerID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptTransactionHeader.BusinessPartnerTypeID AND AR_SET_BusinessPartnerTypes.FK_CodeCombinationID = GL_TransactionDetail.CodeCombinationID Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID WHERE AR_ReceiptTransactionHeader.CompanyID = @companyId AND AR_ReceiptTransactionHeader.PeriodID = @PeriodId AND AR_ReceiptTransactionHeader.DocumentDate< @FromDate --AND AR_ReceiptTransactionHeader.ReversalComments is null {6} And Set_DocumentType.DocumentType like 'Receipt%Loan Recovery' AND (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.PaymentServerOrderNo, Fintab.Narration, FinTab.SupplierAccountCode, FinTab.CodeDescription
) AS FINTAB GROUP BY DocumentType, CustomerID, CustomerName, InstrumentNo, Comments, DocumentNo, DocumentDate,FINTAB.CostCenterName,FINTAB.CodeCombinationID ,FINTAB.CodeDescription
----------------------------Al Imdad ----------------------Import
UNION All Select distinct fintab1.DocumentDate, fintab1.DocumentType, fintab1.CostCenterName, fintab1.CustomerID, fintab1.CustomerName, fintab1.DocumentNo, Sum(fintab1.Debit) As Debit, Sum(Credit) As Credit, fintab1.InstrumentNo, fintab1.Comments, fintab1.SupplierAccountCode As CodeCombinationID, fintab1.CodeDescription From ( Select distinct AP_PurchaseOrderHeader.DocumentDate, SET_DocumentType.DocumentType, '' as CostCenterName, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName,GL_TransactionHeader.DocumentNo as DocumentNo, Case when GL_TransactionDetail.TransactionType = 'Debit' then (AP_PurchaseOrderHeader.AmountIndollar*ISNULL(Rate,1)) else 0 end As Debit, Case when GL_TransactionDetail.TransactionType = 'Credit' then (AP_PurchaseOrderHeader.AmountIndollar*ISNULL(Rate,1)) else 0 end As Credit, 0 As InstrumentNo, GL_TransactionHeader.Narration As Comments, GL_codecombinationDetail.CodeCombinationID as SupplierAccountCode, GL_codecombinationDetail.Description as CodeDescription FROM SET_DocumentType INNER JOIN AP_PurchaseOrderHeader ON SET_DocumentType.CompanyID = AP_PurchaseOrderHeader.CompanyID AND SET_DocumentType.PeriodID = AP_PurchaseOrderHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AP_PurchaseOrderHeader.TypeCode AND MenuID in (Select MenuID from ApplicationMenu Where MenuPath='/ALImdad/Transaction/ImportDocument_frm.aspx') INNER JOIN AR_SET_Customer ON AP_PurchaseOrderHeader.VendorID = AR_SET_Customer.CustomerID --AND AP_PurchaseOrderHeader.CompanyID = AR_SET_Customer.CompanyID AND AP_PurchaseOrderHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 AND AR_SET_Customer.IsActive = 1 inner join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = AP_PurchaseOrderHeader.DocumentNumber and GL_TransactionHeader.DocumentTypeID = AP_PurchaseOrderHeader.TypeCode and AP_PurchaseOrderHeader.FiscalID = GL_TransactionHeader.FiscalID INNER JOIN dbo.GL_TransactionDetail ON GL_TransactionHeader.TransactionID = GL_TransactionDetail.TransactionID AND GL_TransactionHeader.PeriodID = GL_TransactionDetail.PeriodID AND GL_TransactionHeader.CompanyID = GL_TransactionDetail.CompanyID AND GL_TransactionDetail.TransactionType = 'Credit' inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID
INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND AP_PurchaseOrderHeader.DocumentDate < @FromDate and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0} ) fintab1 Group By fintab1.DocumentDate, fintab1.DocumentType, fintab1.CostCenterName, fintab1.CustomerID, fintab1.CustomerName, fintab1.DocumentNo, fintab1.InstrumentNo, fintab1.Comments, fintab1.SupplierAccountCode, fintab1.CodeDescription UNION ALL -------------Logistic Service Select distinct fintab2.DocumentDate, fintab2.DocumentType, fintab2.CostCenterName, fintab2.CustomerID, fintab2.CustomerName, fintab2.DocumentNo, Sum(fintab2.Debit) As Debit, Sum(Credit) As Credit, fintab2.InstrumentNo, fintab2.Comments, fintab2.SupplierAccountCode As CodeCombinationID, fintab2.CodeDescription From ( Select IMP_LogisticServices.DocumentDate, SET_DocumentType.DocumentType, '' as CostCenterName, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName,GL_TransactionHeader.DocumentNo as DocumentNo, Case when GL_TransactionDetail.TransactionType = 'Debit' then (IMP_LogisticServices.TotalLogisticCost) else 0 end As Debit, Case when GL_TransactionDetail.TransactionType = 'Credit' then (IMP_LogisticServices.TotalLogisticCost) else 0 end As Credit, 0 As InstrumentNo, GL_TransactionHeader.Narration As Comments, GL_codecombinationDetail.CodeCombinationID as SupplierAccountCode, GL_codecombinationDetail.Description as CodeDescription FROM IMP_LogisticServices INNER JOIN GL_TransactionHeader ON GL_TransactionHeader.CompanyID = IMP_LogisticServices.CompanyID AND GL_TransactionHeader.PeriodID = IMP_LogisticServices.PeriodID AND GL_TransactionHeader.DocumentNo = IMP_LogisticServices.DocumentNo INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = GL_TransactionHeader.CompanyID AND SET_DocumentType.PeriodID = GL_TransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID AND SET_DocumentType.DocumentType='Logistic Services' INNER JOIN AR_SET_Customer ON IMP_LogisticServices.LogisticSupplierID = AR_SET_Customer.CustomerID --AND IMP_LogisticServices.CompanyID = AR_SET_Customer.CompanyID AND IMP_LogisticServices.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 AND AR_SET_Customer.IsActive = 1 INNER JOIN dbo.GL_TransactionDetail ON GL_TransactionHeader.TransactionID = GL_TransactionDetail.TransactionID AND GL_TransactionHeader.PeriodID = GL_TransactionDetail.PeriodID AND GL_TransactionHeader.CompanyID = GL_TransactionDetail.CompanyID AND GL_TransactionDetail.TransactionType = 'Credit' inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID
INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode AND BusinessPartnerName like '%Logistic%'
WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND IMP_LogisticServices.DocumentDate < @FromDate and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0} ) as fintab2 Group By fintab2.DocumentDate, fintab2.DocumentType, fintab2.CostCenterName, fintab2.CustomerID, fintab2.CustomerName, fintab2.DocumentNo, fintab2.InstrumentNo, fintab2.Comments, fintab2.SupplierAccountCode, fintab2.CodeDescription
UNION ALL
----------------Custom Clearing Select GL_TransactionHeader.DocumentDate, SET_DocumentType.DocumentType, '' as CostCenterName, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName,GL_TransactionHeader.DocumentNo as DocumentNo, Case when GL_TransactionDetail.TransactionType = 'Debit' then (IMP_CustomClearing.TotalInvoiceAmount) else 0 end As Debit, Case when GL_TransactionDetail.TransactionType = 'Credit' then (IMP_CustomClearing.TotalInvoiceAmount) else 0 end As Credit, 0 As InstrumentNo, GL_TransactionHeader.Narration As Comments, GL_codecombinationDetail.CodeCombinationID as SupplierAccountCode, GL_codecombinationDetail.Description as CodeDescription FROM GL_TransactionHeader INNER JOIN GL_TransactionDetail ON GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID AND GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID AND GL_TransactionDetail.PeriodID=GL_TransactionHeader.PeriodID AND GL_TransactionDetail.TransactionType = 'Credit' AND GL_TransactionDetail.Status=1 INNER JOIN IMP_CustomClearing ON IMP_CustomClearing.CustomClearingID = GL_TransactionDetail.SourceHeaderID AND GL_TransactionHeader.Status=1 INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = GL_TransactionHeader.CompanyID AND SET_DocumentType.PeriodID = GL_TransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID AND SET_DocumentType.DocumentType='Custom Clearing' INNER JOIN AR_SET_Customer ON IMP_CustomClearing.ClearingAgentID = AR_SET_Customer.CustomerID AND AR_SET_Customer.Status = 1 AND AR_SET_Customer.IsActive = 1 inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID
INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID
INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode
WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND IMP_CustomClearing.CCDate < @FromDate and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0}
------------------- Transport UNION ALL Select Distinct GL_TransactionHeader.DocumentDate, SET_DocumentType.DocumentType, '' as CostCenterName, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName,GL_TransactionHeader.DocumentNo as DocumentNo, Case when GL_TransactionDetail.TransactionType = 'Debit' then (Set_ContainerTransportationandUnloading.TotalTransAmount) else 0 end As Debit, Case when GL_TransactionDetail.TransactionType = 'Credit' then (Set_ContainerTransportationandUnloading.TotalTransAmount) else 0 end As Credit, 0 As InstrumentNo, GL_TransactionHeader.Narration As Comments, GL_codecombinationDetail.CodeCombinationID as SupplierAccountCode, GL_codecombinationDetail.Description as CodeDescription FROM GL_TransactionHeader INNER JOIN GL_TransactionDetail ON GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID AND GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID AND GL_TransactionDetail.PeriodID=GL_TransactionHeader.PeriodID AND GL_TransactionHeader.Status=1 AND GL_TransactionDetail.TransactionType = 'Credit' INNER JOIN Set_ContainerTransportationandUnloading ON Set_ContainerTransportationandUnloading.ContainerTransportationID = GL_TransactionDetail.SourceHeaderID AND GL_TransactionHeader.Status=1 INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = GL_TransactionHeader.CompanyID AND SET_DocumentType.PeriodID = GL_TransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID AND SET_DocumentType.DocumentType='Transportation' INNER JOIN AR_SET_Customer ON Set_ContainerTransportationandUnloading.TransporterID = AR_SET_Customer.CustomerID AND AR_SET_Customer.Status = 1 AND AR_SET_Customer.IsActive = 1
INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID
inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = AR_SET_BusinessPartnerTypes.FK_CodeCombinationID INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode AND AR_SET_BusinessPartner.BusinessPartnerName='Transporter' WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND GL_TransactionHeader.DocumentDate< @FromDate and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0}
UNION ALL Select distinct fintab3.DocumentDate, fintab3.DocumentType, fintab3.CostCenterName, fintab3.CustomerID, fintab3.CustomerName, fintab3.DocumentNo, Sum(fintab3.Debit) As Debit, Sum(fintab3.Credit) As Credit, fintab3.InstrumentNo, fintab3.Comments, fintab3.SupplierAccountCode As CodeCombinationID, fintab3.CodeDescription From ( Select Distinct GL_TransactionHeader.DocumentDate, SET_DocumentType.DocumentType, '' as CostCenterName, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName,GL_TransactionHeader.DocumentNo as DocumentNo, Case when GL_TransactionDetail.TransactionType = 'Debit' then ([Fabrics_LoadingAndUnloading].TotalUnloadAmount) else 0 end As Debit, Case when GL_TransactionDetail.TransactionType = 'Credit' then ([Fabrics_LoadingAndUnloading].TotalUnloadAmount) else 0 end As Credit, 0 As InstrumentNo, GL_TransactionHeader.Narration As Comments, GL_codecombinationDetail.CodeCombinationID as SupplierAccountCode, GL_codecombinationDetail.Description as CodeDescription FROM GL_TransactionHeader INNER JOIN GL_TransactionDetail ON GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID AND GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID AND GL_TransactionDetail.PeriodID=GL_TransactionHeader.PeriodID AND GL_TransactionHeader.Status=1 AND GL_TransactionDetail.TransactionType = 'Credit' INNER JOIN [Fabrics_LoadingAndUnloading] ON [Fabrics_LoadingAndUnloading].LoadingUnloadingID = GL_TransactionDetail.SourceHeaderID AND GL_TransactionHeader.Status=1 AND [Fabrics_LoadingAndUnloading].StatusCode=1 INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = GL_TransactionHeader.CompanyID AND SET_DocumentType.PeriodID = GL_TransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID AND SET_DocumentType.DocumentType like '%Loading%' INNER JOIN AR_SET_Customer ON [Fabrics_LoadingAndUnloading].ContractorID = AR_SET_Customer.CustomerID
AND AR_SET_Customer.Status = 1 AND AR_SET_Customer.IsActive = 1
INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = AR_SET_BusinessPartnerTypes.FK_CodeCombinationID
INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode AND (AR_SET_BusinessPartner.BusinessPartnerName='Loading_Contractor/Unloading_Contractor') WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND GL_TransactionHeader.DocumentDate < @FromDate and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0}
) as fintab3 Group By fintab3.DocumentDate, fintab3.DocumentType, fintab3.CostCenterName, fintab3.CustomerID, fintab3.CustomerName, fintab3.DocumentNo, fintab3.InstrumentNo, fintab3.Comments, fintab3.SupplierAccountCode, fintab3.CodeDescription
) as TABopening -- For Transation type Filter --where TABopening.Amount = 0 GROUP BY TABopening.CustomerID, TABopening.CustomerName,CodeCombinationID,CodeDescription
union all -----------------------END OPENING
---------- Sales Invoice Header ---------- Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, '' As InstrumentNo, FinTab.Description As Comments, FinTab.CodeCombinationID ,FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, Sal_InvoiceHeader.Description, GL_TransactionDetail.CodeCombinationID, Case When GL_TransactionDetail.TransactionType = 'Debit' Then GL_TransactionDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then GL_TransactionDetail.Amount Else 0 End As Credit ,GL_codecombinationDetail.Description as CodeDescription From GL_TransactionHeader Inner Join GL_TransactionDetail On GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID And GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID And GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID And GL_TransactionDetail.Status = 1 And GL_TransactionDetail.TransactionType = 'Debit' Inner Join Sal_InvoiceHeader On Sal_InvoiceHeader.CompanyID = GL_TransactionHeader.CompanyID And Sal_InvoiceHeader.PeriodID = GL_TransactionHeader.PeriodID And Sal_InvoiceHeader.InvoiceType = GL_TransactionHeader.DocumentTypeID And Sal_InvoiceHeader.InvoiceNumber = GL_TransactionHeader.DocumentNo And Sal_InvoiceHeader.Status = 1 And Sal_InvoiceHeader.StatusCode = 1 and Sal_InvoiceHeader.FiscalID = GL_TransactionHeader.FiscalID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = GL_TransactionHeader.CompanyID And Set_DocumentType.PeriodID = GL_TransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And Set_DocumentType.IsActive = 1 And Set_DocumentType.Status = 1 Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = Sal_InvoiceHeader.PeriodID And AR_Set_Customer.CustomerID = Sal_InvoiceHeader.CustomerID And AR_Set_Customer.IsActive = 1 And AR_Set_Customer.Status = 1 Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID
Where GL_TransactionHeader.CompanyID = @CompanyID and GL_TransactionHeader.PeriodID = @PeriodID and GL_TransactionHeader.ReversalID is null and GL_TransactionHeader.ReversalDate is null and isnull(GL_TransactionHeader.IsReversed,0) = 0 and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) AND GL_TransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.Description, FinTab.CodeCombinationID ,FinTab.CodeDescription
Union All ---------- Sales Invoice Customer Detail ---------- Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, '' As InstrumentNo, FinTab.Narration As Comments, FinTab.CustomerAccountCode As CodeCombinationID ,FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, Sal_InvoiceCustomerDetail.Narration, Sal_InvoiceCustomerDetail.CustomerAccountCode, Case When GL_TransactionDetail.TransactionType = 'Debit' Then Sal_InvoiceCustomerDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then Sal_InvoiceCustomerDetail.Amount Else 0 End As Credit ,GL_codecombinationDetail.Description as CodeDescription From GL_TransactionHeader Inner Join GL_TransactionDetail On GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID And GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID And GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID And GL_TransactionDetail.Status = 1 Inner Join Sal_InvoiceHeader On Sal_InvoiceHeader.CompanyID = GL_TransactionHeader.CompanyID And Sal_InvoiceHeader.PeriodID = GL_TransactionHeader.PeriodID And Sal_InvoiceHeader.InvoiceType = GL_TransactionHeader.DocumentTypeID And Sal_InvoiceHeader.InvoiceNumber = GL_TransactionHeader.DocumentNo And Sal_InvoiceHeader.Status = 1 And Sal_InvoiceHeader.StatusCode = 1 and Sal_InvoiceHeader.FiscalID = GL_TransactionHeader.FiscalID Inner Join Sal_InvoiceCustomerDetail On Sal_InvoiceCustomerDetail.CompanyID = Sal_InvoiceHeader.CompanyID And Sal_InvoiceCustomerDetail.PeriodID = Sal_InvoiceHeader.PeriodID And Sal_InvoiceCustomerDetail.InvoiceHeaderID = Sal_InvoiceHeader.InvoiceID And Sal_InvoiceCustomerDetail.CustomerAccountCode = GL_TransactionDetail.CodeCombinationID And Sal_InvoiceCustomerDetail.TransactionType = GL_TransactionDetail.TransactionType Inner Join Set_DocumentType On Set_DocumentType.CompanyID = GL_TransactionHeader.CompanyID And Set_DocumentType.PeriodID = GL_TransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And Set_DocumentType.IsActive = 1 And Set_DocumentType.Status = 1 Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = Sal_InvoiceCustomerDetail.PeriodID And AR_Set_Customer.CustomerID = Sal_InvoiceCustomerDetail.CustomerID And AR_Set_Customer.IsActive = 1 And AR_Set_Customer.Status = 1 Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID Where GL_TransactionHeader.CompanyID = @CompanyID and GL_TransactionHeader.PeriodID = @PeriodID --And IsNull(Sal_InvoiceHeader.IsReversed, 0) = 0 And Sal_InvoiceHeader.ReversalID is null {5} and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) AND GL_TransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.Narration, FinTab.CustomerAccountCode ,FinTab.CodeDescription
