ID And AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID And AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID And AR_ReceiptCustomerDetail.CustomerAccountCode = GL_TransactionDetail.CodeCombinationID And AR_ReceiptCustomerDetail.TransactionType = GL_TransactionDetail.TransactionType Inner Join Set_DocumentType On Set_DocumentType.CompanyID = GL_TransactionHeader.CompanyID And Set_DocumentType.PeriodID = GL_TransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And Set_DocumentType.IsActive = 1 And Set_DocumentType.Status = 1 Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = AR_ReceiptCustomerDetail.PeriodID And AR_Set_Customer.CustomerID = AR_ReceiptCustomerDetail.CustomerID And AR_Set_Customer.IsActive = 1 And AR_Set_Customer.Status = 1 Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID Where GL_TransactionHeader.CompanyID = @CompanyID and GL_TransactionHeader.PeriodID = @PeriodID --And AR_ReceiptTransactionHeader.ReversalComments is null {6} and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) AND GL_TransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.PaymentServerOrderNo, FinTab.Narration, FinTab.CustomerAccountCode ,FinTab.CodeDescription
Union All -------------------------- Vendor Invice imtiaz
select distinct TABInvoice.DocumentDate,TABInvoice.DocumentType,CostCenterName, TABInvoice.CustomerID,CustomerName,TABInvoice.DocumentNo,Debit, TABInvoice.Credit, InstrumentNo,Comments,CodeCombinationID ,CodeDescription from (
SELECT distinct AR_InvoiceHeader.companyID, Set_DocumentType.TransactionType, case when AR_SET_BusinessPartnerTypes.TypeCode is null then ( select top 1 CUS.TypeCode from AR_SET_BusinessPartnerTypes CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.BusinessPartnerID AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID ) else AR_SET_BusinessPartnerTypes.TypeCode end as TypeCode, case when AR_InvoiceHeader.vendorID is null then ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID ) else ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceHeader.vendorID = CUS.CustomerID --AND AR_InvoiceHeader.CompanyID = CUS.CompanyID AND AR_InvoiceHeader.PeriodID = CUS.PeriodID ) end as CustomerID, SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate, case when AR_InvoiceHeader.vendorID is null then ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID ) else ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceHeader.vendorID = CUS.CustomerID --AND AR_InvoiceHeader.CompanyID = CUS.CompanyID AND AR_InvoiceHeader.PeriodID = CUS.PeriodID ) end as CustomerName, AR_InvoiceSupplierDetail.InvoiceSupplierID as SourceID, case when AR_InvoiceHeader.vendorID is null then (Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount else AR_InvoiceSupplierDetail.Amount * -1 end) else ( Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceHeader.AmountPaid when SET_DocumentType.DocumentType = 'Debit Note' then AR_InvoiceHeader.AmountPaid else (Isnull(AR_InvoiceHeader.AmountPaid,0) + Isnull(AR_InvoiceHeader.FreightAmount,0) - ISnull(AR_InvoiceHeader.OtherAmount,0)) * -1 end ) end as Amount, ISNULL( case when AR_InvoiceHeader.vendorID is null then (Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount end) else ( Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceHeader.AmountPaid when SET_DocumentType.DocumentType = 'Debit Note' then AR_InvoiceHeader.AmountPaid end ) end,0) Debit ,
case when AR_InvoiceHeader.vendorID is null then (Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount end) else ( Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then (Isnull(AR_InvoiceHeader.AmountPaid,0) + Isnull(AR_InvoiceHeader.FreightAmount,0) - ISnull(AR_InvoiceHeader.OtherAmount,0)) when SET_DocumentType.DocumentType= 'Debit Note' then (Isnull(AR_InvoiceHeader.AmountPaid,0) + Isnull(AR_InvoiceHeader.FreightAmount,0) - ISnull(AR_InvoiceHeader.OtherAmount,0)) end ) end Credit ,
'0' AS InstrumentNo, AR_InvoiceHeader.Description AS Comments,AR_InvoiceSupplierDetail.Narration as DetailNarration ,AR_InvoiceHeader.VendorReferenceNumber as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, AR_InvoiceHeader.InvoiceDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,'' CostCenterName ,AR_SET_BusinessPartnerTypes.FK_CodeCombinationID as CodeCombinationID ,GL_codecombinationDetail.Description as CodeDescription FROM SET_DocumentType INNER JOIN AR_InvoiceHeader ON SET_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_InvoiceHeader.InvoiceType AND AR_InvoiceHeader.Status = 1 AND AR_InvoiceHeader.StatusCode = 1 INNER JOIN GL_TransactionHeader ON GL_TransactionHeader.DocumentNo = AR_InvoiceHeader.InvoiceNumber AND GL_TransactionHeader.DocumentTypeID = AR_InvoiceHeader.InvoiceType AND GL_TransactionHeader.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND GL_TransactionHeader.FiscalID = AR_InvoiceHeader.FiscalID AND GL_TransactionHeader.Status = 1 --INNER JOIN GL_TransactionDetail ON GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID -- AND GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID AND GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID -- AND GL_TransactionDetail.Status = 1
LEFT JOIN AR_InvoiceDetail on AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID LEFT JOIN AR_InvoiceSupplierDetail on AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID LEFT JOIN AR_SET_Customer ASCUS ON AR_InvoiceSupplierDetail.SupplierID = ASCUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = ASCUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = ASCUS.PeriodID AND ASCUS.Status = 1
left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.vENDORid AND AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode Inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = AR_SET_BusinessPartnerTypes. FK_CodeCombinationID AND AR_SET_BusinessPartnerTypes.TypeCode=1 WHERE AR_InvoiceHeader.CompanyID = @companyId AND AR_InvoiceHeader.PeriodID = @PeriodId AND AR_InvoiceHeader.InvoiceDate BETWEEN @FromDate AND @ToDate and (AR_SET_BusinessPartnerTypes.FK_CodeCombinationID = @AccountCode OR @AccountCode is null) AND AR_InvoiceHeader.InvoiceDate < @FromDate
) TABInvoice where TABInvoice.companyID = @companyId {3} UNION ALL ---------- Purchase Invoice Header ---------- Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, '' As InstrumentNo, FinTab.Description As Comments, FinTab.CodeCombinationID ,FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AR_InvoiceHeader.Description, GL_TransactionDetail.CodeCombinationID, Case When GL_TransactionDetail.TransactionType = 'Debit' Then GL_TransactionDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then GL_TransactionDetail.Amount Else 0 End As Credit ,GL_codecombinationDetail.Description as CodeDescription From GL_TransactionHeader Inner Join GL_TransactionDetail On GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID And GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID And GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID And GL_TransactionDetail.Status = 1 Inner Join AR_InvoiceHeader On AR_InvoiceHeader.CompanyID = GL_TransactionHeader.CompanyID And AR_InvoiceHeader.PeriodID = GL_TransactionHeader.PeriodID And AR_InvoiceHeader.InvoiceType = GL_TransactionHeader.DocumentTypeID And AR_InvoiceHeader.InvoiceNumber = GL_TransactionHeader.DocumentNo And AR_InvoiceHeader.Status = 1 And AR_InvoiceHeader.StatusCode = 1 and AR_InvoiceHeader.FiscalID = GL_TransactionHeader.FiscalID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = GL_TransactionHeader.CompanyID And Set_DocumentType.PeriodID = GL_TransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And Set_DocumentType.IsActive = 1 And Set_DocumentType.Status = 1 Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = AR_InvoiceHeader.PeriodID And AR_Set_Customer.CustomerID = AR_InvoiceHeader.VendorID And AR_Set_Customer.IsActive = 1 And AR_Set_Customer.Status = 1 Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID Inner Join AR_SET_BusinessPartnerTypes On AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceHeader.CompanyID And AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID And AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.VendorID And AR_SET_BusinessPartnerTypes.TypeCode = AR_InvoiceHeader.BusinessPartnerTypeID And AR_SET_BusinessPartnerTypes.FK_CodeCombinationID = GL_TransactionDetail.CodeCombinationID Where GL_TransactionHeader.CompanyID = @CompanyID and GL_TransactionHeader.PeriodID = @PeriodID -- and GL_TransactionDetail.TransactionType = 'Credit' AND (dbo.GL_TransactionDetail.CodeCombinationID In (SELECT Distinct DefaultAccountCode FROM dbo.SET_DocumentType WHERE (DocumentType Like 'Advance Against PO%') AND (CompanyID = @CompanyID) AND (PeriodID = @PeriodID))) AND (dbo.GL_TransactionDetail.TransactionType = 'Credit') and AR_InvoiceHeader.IsReversed is null and AR_InvoiceHeader.ReversalID is null and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) AND GL_TransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.Description, FinTab.CodeCombinationID ,FinTab.CodeDescription
