ersalID is null AND GL_TransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate and GL_TransactionDetail.codecombinationID in (SELECT Distinct DefaultAccountCode FROM SET_DocumentType WHERE DocumentType like 'Advance Against PO%' AND CompanyID = @CompanyID AND PeriodID = @PeriodID) and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.Description, FinTab.CodeCombinationID, FinTab.CodeDescription
