---------- Purchase Invoice Supplier Detail ---------- Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, '' As InstrumentNo, FinTab.Narration As Comments, FinTab.SupplierAccountCode As CodeCombinationID ,FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AR_InvoiceSupplierDetail.SupplierAccountCode, AR_InvoiceSupplierDetail.Narration, Case When GL_TransactionDetail.TransactionType = 'Debit' Then AR_InvoiceSupplierDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then AR_InvoiceSupplierDetail.Amount Else 0 End As Credit ,GL_codecombinationDetail.Description as CodeDescription, AR_InvoiceSupplierDetail.InvoiceSupplierID From GL_TransactionHeader Inner Join GL_TransactionDetail On GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID And GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID And GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID And GL_TransactionDetail.Status = 1 Inner Join AR_InvoiceHeader On AR_InvoiceHeader.CompanyID = GL_TransactionHeader.CompanyID And AR_InvoiceHeader.PeriodID = GL_TransactionHeader.PeriodID And AR_InvoiceHeader.InvoiceType = GL_TransactionHeader.DocumentTypeID And AR_InvoiceHeader.InvoiceNumber = GL_TransactionHeader.DocumentNo And AR_InvoiceHeader.Status = 1 And AR_InvoiceHeader.StatusCode = 1 and AR_InvoiceHeader.FiscalID = GL_TransactionHeader.FiscalID Inner Join AR_InvoiceSupplierDetail On AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID And AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID And AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID And AR_InvoiceSupplierDetail.SupplierAccountCode = GL_TransactionDetail.CodeCombinationID And AR_InvoiceSupplierDetail.TransactionType = GL_TransactionDetail.TransactionType Inner Join Set_DocumentType On Set_DocumentType.CompanyID = GL_TransactionHeader.CompanyID And Set_DocumentType.PeriodID = GL_TransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And Set_DocumentType.IsActive = 1 And Set_DocumentType.Status = 1 Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = AR_InvoiceSupplierDetail.PeriodID And AR_Set_Customer.CustomerID = AR_InvoiceSupplierDetail.SupplierID And AR_Set_Customer.IsActive = 1 And AR_Set_Customer.Status = 1 Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID Where GL_TransactionHeader.CompanyID = @CompanyID and GL_TransactionHeader.PeriodID = @PeriodID --And IsNull(AR_InvoiceHeader.IsReversed, 0) = 0 And AR_InvoiceHeader.ReversalID is null {7} and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) AND GL_TransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.Narration, FinTab.SupplierAccountCode ,FinTab.CodeDescription
Union All ---------- Payment Supplier Detail ---------- Select FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, FinTab.PaymentServerOrderNo As InstrumentNo, Fintab.Narration As Comments, FinTab.SupplierAccountCode As CodeCombinationID ,FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AP_PaymentHeader.PaymentServerOrderNo, AP_PaymentSupplierDetail.Narration, AP_PaymentSupplierDetail.SupplierAccountCode, Case When GL_TransactionDetail.TransactionType = 'Debit' Then AP_PaymentSupplierDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then AP_PaymentSupplierDetail.Amount Else 0 End As Credit ,GL_codecombinationDetail.Description as CodeDescription ,AP_PaymentSupplierDetail.PaymentSupplierID From GL_TransactionHeader Inner Join GL_TransactionDetail On GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID And GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID And GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID And GL_TransactionDetail.Status = 1 Inner Join AP_PaymentHeader On AP_PaymentHeader.CompanyID = GL_TransactionHeader.CompanyID And AP_PaymentHeader.PeriodID = GL_TransactionHeader.PeriodID And AP_PaymentHeader.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And AP_PaymentHeader.DocumentNo = GL_TransactionHeader.DocumentNo And AP_PaymentHeader.Status = 1 And AP_PaymentHeader.StatusCode = 1 and AP_PaymentHeader.FiscalID = GL_TransactionHeader.FiscalID Inner Join AP_PaymentSupplierDetail On AP_PaymentSupplierDetail.CompanyID = AP_PaymentHeader.CompanyID And AP_PaymentSupplierDetail.PeriodID = AP_PaymentHeader.PeriodID And AP_PaymentSupplierDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID And AP_PaymentSupplierDetail.SupplierAccountCode = GL_TransactionDetail.CodeCombinationID And AP_PaymentSupplierDetail.TransactionType = GL_TransactionDetail.TransactionType Inner Join Set_DocumentType On Set_DocumentType.CompanyID = GL_TransactionHeader.CompanyID And Set_DocumentType.PeriodID = GL_TransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And Set_DocumentType.IsActive = 1 And Set_DocumentType.Status = 1 Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = AP_PaymentSupplierDetail.PeriodID And AR_Set_Customer.CustomerID = AP_PaymentSupplierDetail.SupplierID And AR_Set_Customer.IsActive = 1 And AR_Set_Customer.Status = 1 Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID Where GL_TransactionHeader.CompanyID = @CompanyID and GL_TransactionHeader.PeriodID = @PeriodID --And AP_PaymentHeader.ReversalComments is null {8} and Set_DocumentType.DocumentType not like 'Grower Loan Payment' and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) AND GL_TransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.PaymentServerOrderNo, Fintab.Narration, FinTab.SupplierAccountCode ,FinTab.CodeDescription
union all ---------- Payment Supplier Detail ---------- OPENING Select FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, FinTab.PaymentServerOrderNo As InstrumentNo, Fintab.Narration As Comments, FinTab.SupplierAccountCode As CodeCombinationID, FinTab.CodeDescription From ( Select distinct Ap_paymentHeader.DocumentDate, Set_DocumentType.DocumentType, '' as CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, Ap_paymentHeader.DocumentNo, AP_PaymentHeader.PaymentServerOrderNo, AP_PaymentSupplierDetail.Narration, AP_PaymentSupplierDetail.SupplierAccountCode, Case When AP_PaymentSupplierDetail.TransactionType = 'Debit' Then AP_PaymentSupplierDetail.Amount Else 0 End As Debit, Case When AP_PaymentSupplierDetail.TransactionType = 'Credit' then AP_PaymentSupplierDetail.Amount Else 0 End As Credit, GL_codecombinationDetail.Description as CodeDescription, AP_PaymentSupplierDetail.PaymentSupplierID From Ap_paymentHeader Inner Join AP_PaymentSupplierDetail On AP_PaymentSupplierDetail.CompanyID = AP_PaymentHeader.CompanyID And AP_PaymentSupplierDetail.PeriodID = AP_PaymentHeader.PeriodID And AP_PaymentSupplierDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = Ap_paymentHeader.CompanyID And Set_DocumentType.PeriodID = Ap_paymentHeader.PeriodID And Set_DocumentType.DocumentTypeID = Ap_paymentHeader.DocumentTypeID And Set_DocumentType.IsActive = 1 And Set_DocumentType.Status = 1 Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = AP_PaymentSupplierDetail.PeriodID And AR_Set_Customer.CustomerID = AP_PaymentSupplierDetail.SupplierID And AR_Set_Customer.IsActive = 1 And AR_Set_Customer.Status = 1 left join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = AP_PaymentSupplierDetail.SupplierAccountCode Where Ap_paymentHeader.CompanyID = @CompanyID and Ap_paymentHeader.PeriodID = @PeriodID --AND AP_PaymentHeader.ReversalComments is null {8} and Set_DocumentType.DocumentType not like 'Grower Loan Payment' and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) AND Ap_paymentHeader.DocumentDate BETWEEN @FromDate AND @ToDate {1} and Set_DocumentType.DocumentType like '%OPENING%' ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.PaymentServerOrderNo, Fintab.Narration, FinTab.SupplierAccountCode, FinTab.CodeDescription
union all -------------------------- Vendor Invice imtiaz
select distinct TABInvoice.DocumentDate,TABInvoice.DocumentType,CostCenterName, TABInvoice.CustomerID,CustomerName,TABInvoice.DocumentNo,Debit , TABInvoice.Credit,InstrumentNo,Comments,CodeCombinationID ,CodeDescription
from (
SELECT distinct AR_InvoiceHeader.companyID, Set_DocumentType.TransactionType, case when AR_SET_BusinessPartnerTypes.TypeCode is null then ( select top 1 CUS.TypeCode from AR_SET_BusinessPartnerTypes CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.BusinessPartnerID AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID ) else AR_SET_BusinessPartnerTypes.TypeCode end as TypeCode, case when AR_InvoiceHeader.vendorID is null then ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID ) else ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceHeader.vendorID = CUS.CustomerID --AND AR_InvoiceHeader.CompanyID = CUS.CompanyID AND AR_InvoiceHeader.PeriodID = CUS.PeriodID ) end as CustomerID, SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate, case when AR_InvoiceHeader.vendorID is null then ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID ) else ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceHeader.vendorID = CUS.CustomerID --AND AR_InvoiceHeader.CompanyID = CUS.CompanyID AND AR_InvoiceHeader.PeriodID = CUS.PeriodID ) end as CustomerName, AR_InvoiceSupplierDetail.InvoiceSupplierID as SourceID, case when AR_InvoiceHeader.vendorID is null then (Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount else AR_InvoiceSupplierDetail.Amount * -1 end) else ( Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceHeader.AmountPaid when SET_DocumentType.DocumentType = 'Debit Note' then AR_InvoiceHeader.AmountPaid else (Isnull(AR_InvoiceHeader.AmountPaid,0) + Isnull(AR_InvoiceHeader.FreightAmount,0) - ISnull(AR_InvoiceHeader.OtherAmount,0)) * -1 end ) end as Amount, ISNULL( case when AR_InvoiceHeader.vendorID is null then (Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount end) else ( Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceHeader.AmountPaid when SET_DocumentType.DocumentType = 'Debit Note' then AR_InvoiceHeader.AmountPaid end ) end,0) Debit ,
case when AR_InvoiceHeader.vendorID is null then (Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount end) else ( Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then (Isnull(AR_InvoiceHeader.AmountPaid,0) + Isnull(AR_InvoiceHeader.FreightAmount,0) - ISnull(AR_InvoiceHeader.OtherAmount,0)) when SET_DocumentType.DocumentType = 'Debit Note' then (Isnull(AR_InvoiceHeader.AmountPaid,0) + Isnull(AR_InvoiceHeader.FreightAmount,0) - ISnull(AR_InvoiceHeader.OtherAmount,0)) end ) end Credit ,
'0' AS InstrumentNo, AR_InvoiceHeader.Description AS Comments,AR_InvoiceSupplierDetail.Narration as DetailNarration ,AR_InvoiceHeader.VendorReferenceNumber as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, AR_InvoiceHeader.InvoiceDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,'' CostCenterName ,AR_SET_BusinessPartnerTypes.FK_CodeCombinationID as CodeCombinationID ,GL_codecombinationDetail.Description as CodeDescription FROM SET_DocumentType INNER JOIN AR_InvoiceHeader ON SET_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_InvoiceHeader.InvoiceType AND AR_InvoiceHeader.Status = 1 AND AR_InvoiceHeader.StatusCode = 1 INNER JOIN GL_TransactionHeader ON GL_TransactionHeader.DocumentNo = AR_InvoiceHeader.InvoiceNumber AND GL_TransactionHeader.DocumentTypeID = AR_InvoiceHeader.InvoiceType AND GL_TransactionHeader.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND GL_TransactionHeader.FiscalID = AR_InvoiceHeader.FiscalID AND GL_TransactionHeader.Status = 1 --INNER JOIN GL_TransactionDetail ON GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID -- AND GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID AND GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID -- AND GL_TransactionDetail.Status = 1
LEFT JOIN AR_InvoiceDetail on AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID LEFT JOIN AR_InvoiceSupplierDetail on AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID LEFT JOIN AR_SET_Customer ASCUS ON AR_InvoiceSupplierDetail.SupplierID = ASCUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = ASCUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = ASCUS.PeriodID AND ASCUS.Status = 1
left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.vENDORid AND AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode Inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = AR_SET_BusinessPartnerTypes. FK_CodeCombinationID AND AR_SET_BusinessPartnerTypes.TypeCode=1 WHERE AR_InvoiceHeader.CompanyID = @companyId AND AR_InvoiceHeader.PeriodID = @PeriodId AND AR_InvoiceHeader.InvoiceDate BETWEEN @FromDate AND @ToDate and (AR_SET_BusinessPartnerTypes.FK_CodeCombinationID = @AccountCode OR @AccountCode is null) AND AR_InvoiceHeader.InvoiceDate BETWEEN @FromDate AND @ToDate
) TABInvoice where TABInvoice.companyID = @companyId {3} UNION ALL ---------- Purchase Invoice Header ---------- DI-Invoice CPR Select FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, FinTab.PaymentServerOrderNo As InstrumentNo, Fintab.Narration As Comments, FinTab.SupplierAccountCode As CodeCombinationID, FinTab.CodeDescription From ( Select distinct AR_InvoiceHeader.InvoiceDate As DocumentDate, Set_DocumentType.DocumentType, '' as CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, AR_InvoiceHeader.InvoiceNumber As DocumentNo, '' As PaymentServerOrderNo, AR_InvoiceHeader.Description As Narration, AR_InvoiceSupplierDetail.SupplierAccountCode, Case When AR_InvoiceSupplierDetail.TransactionType = 'Debit' Then AR_InvoiceSupplierDetail.Amount Else 0 End As Debit, Case When AR_InvoiceSupplierDetail.TransactionType = 'Credit' Then AR_InvoiceSupplierDetail.Amount Else 0 End As Credit, GL_codecombinationDetail.Description as CodeDescription, AR_InvoiceHeader.VendorID, AR_InvoiceSupplierDetail.InvoiceSupplierID From AR_InvoiceHeader Inner Join AR_InvoiceSupplierDetail On AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID And AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID And AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID And Set_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID And Set_DocumentType.DocumentTypeID = AR_InvoiceHeader.InvoiceType And Set_DocumentType.IsActive = 1 And Set_DocumentType.Status = 1 Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = AR_InvoiceSupplierDetail.PeriodID And AR_Set_Customer.CustomerID = AR_InvoiceSupplierDetail.SupplierID And AR_Set_Customer.IsActive = 1 And AR_Set_Customer.Status = 1 Inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = AR_InvoiceSupplierDetail.SupplierAccountCode Where AR_InvoiceHeader.CompanyID = @CompanyID and AR_InvoiceHeader.PeriodID = @PeriodID And IsNull(AR_InvoiceHeader.IsReversed, 0) = 0 And AR_InvoiceHeader.ReversalID is null and Set_DocumentType.DocumentType like '%invoice cpr%' and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) AND AR_InvoiceHeader.InvoiceDate BETWEEN @FromDate AND @ToDate {2} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerName, FinTab.CustomerID, FinTab.DocumentNo, FinTab.PaymentServerOrderNo, Fintab.Narration, FinTab.SupplierAccountCode, FinTab.CodeDescription
Union All ---------- Payment Supplier Detail -----Grower Loan Payment----- Select FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, FinTab.PaymentServerOrderNo As InstrumentNo, Fintab.Narration As Comments, FinTab.SupplierAccountCode As CodeCombinationID, FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AP_PaymentHeader.PaymentServerOrderNo, AP_PaymentSupplierDetail.Narration, AP_PaymentSupplierDetail.SupplierAccountCode, Case When GL_TransactionDetail.TransactionType = 'Debit' Then AP_PaymentSupplierDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then AP_PaymentSupplierDetail.Amount Else 0 End As Credit ,GL_codecombinationDetail.Description as CodeDescription ,AP_PaymentSupplierDetail.PaymentSupplierID From GL_TransactionHeader Inner Join GL_TransactionDetail On GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID And GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID And GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID And GL_TransactionDetail.Status = 1 Inner Join AP_PaymentHeader On AP_PaymentHeader.CompanyID = GL_TransactionHeader.CompanyID And AP_PaymentHeader.PeriodID = GL_TransactionHeader.PeriodID And AP_PaymentHeader.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And AP_PaymentHeader.DocumentNo = GL_TransactionHeader.DocumentNo And AP_PaymentHeader.Status = 1 And AP_PaymentHeader.StatusCode = 1 and AP_PaymentHeader.FiscalID = GL_TransactionHeader.FiscalID Inner Join AP_PaymentSupplierDetail On AP_PaymentSupplierDetail.CompanyID = AP_PaymentHeader.CompanyID And AP_PaymentSupplierDetail.PeriodID = AP_PaymentHeader.PeriodID And AP_PaymentSupplierDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID And AP_PaymentSupplierDetail.TransactionType = GL_TransactionDetail.TransactionType Inner Join Set_DocumentType On Set_DocumentType.CompanyID = GL_TransactionHeader.CompanyID And Set_DocumentType.PeriodID = GL_TransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And Set_DocumentType.IsActive = 1 And Set_DocumentType.Status = 1 Inner Join AR_Set_Customer On AR_Set_Customer.PeriodID = AP_PaymentSupplierDetail.PeriodID And AR_Set_Customer.CustomerID = AP_PaymentSupplierDetail.SupplierID And AR_Set_Customer.IsActive = 1 And AR_Set_Customer.Status = 1 Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID Where GL_TransactionHeader.CompanyID = @CompanyID and GL_TransactionHeader.PeriodID = @PeriodID --And AP_PaymentHeader.ReversalComments is null {8} AND GL_TransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate and Set_DocumentType.DocumentType like 'Grower Loan Payment' and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.PaymentServerOrderNo, Fintab.Narration, FinTab.SupplierAccountCode ,FinTab.CodeDescription
union all -- payment against vendor invoices Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, FinTab.PaymentServerOrderNo As InstrumentNo, Fintab.Narration As Comments, FinTab.SupplierAccountCode As CodeCombinationID ,FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AP_PaymentHeader.PaymentServerOrderNo, ' ' as Narration, GL_TransactionDetail.CodeCombinationID as SupplierAccountCode, Case When GL_TransactionDetail.TransactionType = 'Debit' Then GL_TransactionDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then GL_TransactionDetail.Amount Else 0 End As Credit ,GL_codecombinationDetail.Description as CodeDescription From GL_TransactionHeader Inner Join GL_TransactionDetail On GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID And GL_TransactionDetail.PeriodID = GL_TransactionHeader.PeriodID And GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID And GL_TransactionDetail.Status = 1 --and GL_TransactionDetail.CodeCombinationID in ( --select GL_codecombinationDetail.CodeCombinationID from AR_SET_Customer --inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = AR_Set_Customer.CustomerAccountCCID --Inner Join AP_PaymentHeader On AP_PaymentHeader.CompanyID = GL_TransactionHeader.CompanyID --And AP_PaymentHeader.PeriodID = GL_TransactionHeader.PeriodID And AP_PaymentHeader.DocumentTypeID = GL_TransactionHeader.DocumentTypeID --And AP_PaymentHeader.DocumentNo = GL_TransactionHeader.DocumentNo And AP_PaymentHeader.Status = 1 And AP_PaymentHeader.StatusCode = 1 --where AP_PaymentHeader.VendorID = AR_SET_Customer.CustomerID --AND AP_PaymentHeader.CompanyID = AR_SET_Customer.CompanyID --AND AP_PaymentHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 )
Inner Join AP_PaymentHeader On AP_PaymentHeader.CompanyID = GL_TransactionHeader.CompanyID And AP_PaymentHeader.PeriodID = GL_TransactionHeader.PeriodID And AP_PaymentHeader.DocumentTypeID = GL_TransactionHeader.DocumentTypeID And AP_PaymentHeader.DocumentNo = GL_TransactionHeader.DocumentNo And AP_PaymentHeader.Status = 1 And AP_PaymentHeader.StatusCode = 1 and AP_PaymentHeader.FiscalID = GL_TransactionHeader.FiscalID inner join SET_DocumentType on SET_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID and SET_DocumentType.CompanyID = AP_PaymentHeader.CompanyID and SET_DocumentType.PeriodID = AP_PaymentHeader.PeriodID INNER JOIN SET_Bucket ON AP_PaymentHeader.CompanyID = SET_Bucket.CompanyID and SET_Bucket.Status = 1 and SET_Bucket.IsActive = 1 INNER JOIN AR_SET_Customer ON AP_PaymentHeader.VendorID = AR_SET_Customer.CustomerID --AND AP_PaymentHeader.CompanyID = AR_SET_Customer.CompanyID AND AP_PaymentHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = AR_Set_Customer.CustomerAccountCCID Where GL_TransactionHeader.CompanyID = @CompanyID and GL_TransactionHeader.PeriodID = @PeriodID and GL_TransactionDetail.TransactionType = 'Debit' --And AP_PaymentHeader.ReversalComments is null {8} AND GL_TransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate and SET_DocumentType.DocumentType not like 'Advance Against PO%' and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.PaymentServerOrderNo, Fintab.Narration, FinTab.SupplierAccountCode ,FinTab.CodeDescription
union all
----------- Advance Against PO
Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, FinTab.PaymentServerOrderNo As InstrumentNo, Fintab.Narration As Comments, FinTab.SupplierAccountCode As CodeCombinationID ,FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AP_PaymentHeader.PaymentServerOrderNo, ' ' as Narration, GL_TransactionDetail.CodeCombinationID as SupplierAccountCode, Case When GL_TransactionDetail.TransactionType = 'Debit' Then GL_TransactionDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then GL_TransactionDetail.Amount Else 0 End As Credit ,GL_codecombinationDetail.Description as CodeDescription FROM SET_DocumentType INNER JOIN AP_PaymentHeader ON SET_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND SET_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AP_PaymentHeader.documentTypeID AND AP_PaymentHeader .Status = 1 AND AP_PaymentHeader .StatusCode = 1
inner JOIN AR_SET_Customer ON AP_PaymentHeader.VendorID = AR_SET_Customer.CustomerID --AND AP_PaymentHeader.CompanyID = AR_SET_Customer.CompanyID AND AP_PaymentHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 inner join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = AP_PaymentHeader.documentNo and GL_TransactionHeader.DocumentTypeID = AP_PaymentHeader.DocumentTypeID and AP_PaymentHeader.FiscalID = GL_TransactionHeader.FiscalID INNER JOIN dbo.GL_TransactionDetail ON dbo.GL_TransactionHeader.TransactionID = dbo.GL_TransactionDetail.TransactionID AND dbo.GL_TransactionHeader.PeriodID = dbo.GL_TransactionDetail.PeriodID AND dbo.GL_TransactionHeader.CompanyID = dbo.GL_TransactionDetail.CompanyID
AND (dbo.GL_TransactionDetail.CodeCombinationID = (SELECT Max(DefaultAccountCode) FROM dbo.SET_DocumentType WHERE (DocumentType like 'Advance Against PO%') AND (CompanyID = @CompanyID) AND (PeriodID = @PeriodID) And DefaultAccountCode is not null)) AND (dbo.GL_TransactionDetail.TransactionType = 'Debit')
left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AP_PaymentHeader.VendorID AND AR_SET_BusinessPartnerTypes.CompanyID = AP_PaymentHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AP_PaymentHeader.PeriodID
LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = AR_Set_Customer.CustomerAccountCCID WHERE AP_PaymentHeader.CompanyID = @companyId AND AP_PaymentHeader.PeriodID = @PeriodId AND AP_PaymentHeader.DocumentDate BETWEEN @FromDate AND @ToDate --And AP_PaymentHeader.ReversalComments is null {8} and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0}
) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.PaymentServerOrderNo, Fintab.Narration, FinTab.SupplierAccountCode ,FinTab.CodeDescription
union all
---------- Advance Against SO ---------- Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, FinTab.PaymentServerOrderNo As InstrumentNo, Fintab.Narration As Comments, FinTab.SupplierAccountCode As CodeCombinationID, FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.PaymentServerOrderNo, ' ' as Narration, GL_TransactionDetail.CodeCombinationID as SupplierAccountCode, Case When GL_TransactionDetail.TransactionType = 'Debit' Then GL_TransactionDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then GL_TransactionDetail.Amount Else 0 End As Credit, GL_codecombinationDetail.Description as CodeDescription FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 inner JOIN AR_SET_Customer ON AR_ReceiptTransactionHeader.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 inner join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = AR_ReceiptTransactionHeader.documentNo and GL_TransactionHeader.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID and AR_ReceiptTransactionHeader.FiscalID = GL_TransactionHeader.FiscalID INNER JOIN dbo.GL_TransactionDetail ON GL_TransactionHeader.TransactionID = GL_TransactionDetail.TransactionID AND GL_TransactionHeader.PeriodID = GL_TransactionDetail.PeriodID AND GL_TransactionHeader.CompanyID = GL_TransactionDetail.CompanyID AND GL_TransactionDetail.CodeCombinationID = ( SELECT max(DefaultAccountCode) FROM SET_DocumentType WHERE DocumentType like 'Advance Against SO%' AND CompanyID = @CompanyID AND PeriodID = @PeriodID And DefaultAccountCode is not null ) AND GL_TransactionDetail.TransactionType = 'Credit' left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_ReceiptTransactionHeader.CustomerID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_ReceiptTransactionHeader.PeriodID LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = AR_Set_Customer.CustomerAccountCCID WHERE AR_ReceiptTransactionHeader.CompanyID = @companyId AND AR_ReceiptTransactionHeader.PeriodID = @PeriodId AND AR_ReceiptTransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate --And AR_ReceiptTransactionHeader.ReversalComments is NULL {6} and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.PaymentServerOrderNo, Fintab.Narration, FinTab.SupplierAccountCode, FinTab.CodeDescription
union all
---------- Receipt against Invoices - Loan Recovery ---------- Select distinct FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, Sum(FinTab.Debit) As Debit, Sum(Credit) As Credit, FinTab.PaymentServerOrderNo As InstrumentNo, Fintab.Narration As Comments, FinTab.SupplierAccountCode As CodeCombinationID, FinTab.CodeDescription From ( Select distinct GL_TransactionHeader.DocumentDate, Set_DocumentType.DocumentType, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName, GL_TransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.PaymentServerOrderNo, ' ' as Narration, GL_TransactionDetail.CodeCombinationID as SupplierAccountCode, Case When GL_TransactionDetail.TransactionType = 'Debit' Then GL_TransactionDetail.Amount Else 0 End As Debit, Case When GL_TransactionDetail.TransactionType = 'Credit' then GL_TransactionDetail.Amount Else 0 End As Credit, GL_codecombinationDetail.Description as CodeDescription FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 inner JOIN AR_SET_Customer ON AR_ReceiptTransactionHeader.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 inner join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = AR_ReceiptTransactionHeader.documentNo and GL_TransactionHeader.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID and AR_ReceiptTransactionHeader.FiscalID = GL_TransactionHeader.FiscalID INNER JOIN dbo.GL_TransactionDetail ON GL_TransactionHeader.TransactionID = GL_TransactionDetail.TransactionID AND GL_TransactionHeader.PeriodID = GL_TransactionDetail.PeriodID AND GL_TransactionHeader.CompanyID = GL_TransactionDetail.CompanyID AND GL_TransactionDetail.TransactionType = 'Credit' Inner JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_ReceiptTransactionHeader.CustomerID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptTransactionHeader.BusinessPartnerTypeID AND AR_SET_BusinessPartnerTypes.FK_CodeCombinationID = GL_TransactionDetail.CodeCombinationID Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID WHERE AR_ReceiptTransactionHeader.CompanyID = @companyId AND AR_ReceiptTransactionHeader.PeriodID = @PeriodId AND AR_ReceiptTransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate --AND AR_ReceiptTransactionHeader.ReversalComments is null {6} And Set_DocumentType.DocumentType like 'Receipt%Loan Recovery' and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0} ) As FinTab Group By FinTab.DocumentDate, FinTab.DocumentType, FinTab.CostCenterName, FinTab.CustomerID, FinTab.CustomerName, FinTab.DocumentNo, FinTab.PaymentServerOrderNo, Fintab.Narration, FinTab.SupplierAccountCode, FinTab.CodeDescription -----------------------------Al Imdad ---------- ------------import----
UNION All Select distinct fintab1.DocumentDate, fintab1.DocumentType, fintab1.CostCenterName, fintab1.CustomerID, fintab1.CustomerName, fintab1.DocumentNo, Sum(fintab1.Debit) As Debit, Sum(Credit) As Credit, fintab1.InstrumentNo, fintab1.Comments, fintab1.SupplierAccountCode As CodeCombinationID, fintab1.CodeDescription From ( Select distinct AP_PurchaseOrderHeader.DocumentDate, SET_DocumentType.DocumentType, '' as CostCenterName, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName,GL_TransactionHeader.DocumentNo as DocumentNo, Case when GL_TransactionDetail.TransactionType = 'Debit' then (AP_PurchaseOrderHeader.AmountIndollar*ISNULL(Rate,1)) else 0 end As Debit, Case when GL_TransactionDetail.TransactionType = 'Credit' then (AP_PurchaseOrderHeader.AmountIndollar*ISNULL(Rate,1)) else 0 end As Credit, 0 As InstrumentNo, GL_TransactionHeader.Narration As Comments, GL_codecombinationDetail.CodeCombinationID as SupplierAccountCode, GL_codecombinationDetail.Description as CodeDescription FROM SET_DocumentType INNER JOIN AP_PurchaseOrderHeader ON SET_DocumentType.CompanyID = AP_PurchaseOrderHeader.CompanyID AND SET_DocumentType.PeriodID = AP_PurchaseOrderHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AP_PurchaseOrderHeader.TypeCode AND MenuID in (Select MenuID from ApplicationMenu Where MenuPath='/ALImdad/Transaction/ImportDocument_frm.aspx') INNER JOIN AR_SET_Customer ON AP_PurchaseOrderHeader.VendorID = AR_SET_Customer.CustomerID --AND AP_PurchaseOrderHeader.CompanyID = AR_SET_Customer.CompanyID AND AP_PurchaseOrderHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 AND AR_SET_Customer.IsActive = 1 inner join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = AP_PurchaseOrderHeader.DocumentNumber and GL_TransactionHeader.DocumentTypeID = AP_PurchaseOrderHeader.TypeCode and AP_PurchaseOrderHeader.FiscalID = GL_TransactionHeader.FiscalID INNER JOIN dbo.GL_TransactionDetail ON GL_TransactionHeader.TransactionID = GL_TransactionDetail.TransactionID AND GL_TransactionHeader.PeriodID = GL_TransactionDetail.PeriodID AND GL_TransactionHeader.CompanyID = GL_TransactionDetail.CompanyID AND GL_TransactionDetail.TransactionType = 'Credit' inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID
INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode
WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND AP_PurchaseOrderHeader.DocumentDate BETWEEN @FromDate AND @ToDate and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0} ) fintab1 Group By fintab1.DocumentDate, fintab1.DocumentType, fintab1.CostCenterName, fintab1.CustomerID, fintab1.CustomerName, fintab1.DocumentNo, fintab1.InstrumentNo, fintab1.Comments, fintab1.SupplierAccountCode, fintab1.CodeDescription -----------------------------Al Imdad ---------- UNION ALL -------------Logistic Service Select distinct fintab2.DocumentDate, fintab2.DocumentType, fintab2.CostCenterName, fintab2.CustomerID, fintab2.CustomerName, fintab2.DocumentNo, Sum(fintab2.Debit) As Debit, Sum(Credit) As Credit, fintab2.InstrumentNo, fintab2.Comments, fintab2.SupplierAccountCode As CodeCombinationID, fintab2.CodeDescription From ( Select IMP_LogisticServices.DocumentDate, SET_DocumentType.DocumentType, '' as CostCenterName, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName,GL_TransactionHeader.DocumentNo as DocumentNo, Case when GL_TransactionDetail.TransactionType = 'Debit' then (IMP_LogisticServices.TotalLogisticCost) else 0 end As Debit, Case when GL_TransactionDetail.TransactionType = 'Credit' then (IMP_LogisticServices.TotalLogisticCost) else 0 end As Credit, 0 As InstrumentNo, GL_TransactionHeader.Narration As Comments, GL_codecombinationDetail.CodeCombinationID as SupplierAccountCode, GL_codecombinationDetail.Description as CodeDescription FROM IMP_LogisticServices INNER JOIN GL_TransactionHeader ON GL_TransactionHeader.CompanyID = IMP_LogisticServices.CompanyID AND GL_TransactionHeader.PeriodID = IMP_LogisticServices.PeriodID AND GL_TransactionHeader.DocumentNo = IMP_LogisticServices.DocumentNo INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = GL_TransactionHeader.CompanyID AND SET_DocumentType.PeriodID = GL_TransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID AND SET_DocumentType.DocumentType='Logistic Services' INNER JOIN AR_SET_Customer ON IMP_LogisticServices.LogisticSupplierID = AR_SET_Customer.CustomerID --AND IMP_LogisticServices.CompanyID = AR_SET_Customer.CompanyID AND IMP_LogisticServices.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 AND AR_SET_Customer.IsActive = 1 INNER JOIN dbo.GL_TransactionDetail ON GL_TransactionHeader.TransactionID = GL_TransactionDetail.TransactionID AND GL_TransactionHeader.PeriodID = GL_TransactionDetail.PeriodID AND GL_TransactionHeader.CompanyID = GL_TransactionDetail.CompanyID AND GL_TransactionDetail.TransactionType = 'Credit' inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID
