WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND IMP_LogisticServices.DocumentDate BETWEEN @FromDate AND @ToDate and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0} ) as fintab2 Group By fintab2.DocumentDate, fintab2.DocumentType, fintab2.CostCenterName, fintab2.CustomerID, fintab2.CustomerName, fintab2.DocumentNo, fintab2.InstrumentNo, fintab2.Comments, fintab2.SupplierAccountCode, fintab2.CodeDescription
UNION ALL
