------------------- Transport UNION ALL Select distinct GL_TransactionHeader.DocumentDate, SET_DocumentType.DocumentType, '' as CostCenterName, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName,GL_TransactionHeader.DocumentNo as DocumentNo, Case when GL_TransactionDetail.TransactionType = 'Debit' then (Set_ContainerTransportationandUnloading.TotalTransAmount) else 0 end As Debit, Case when GL_TransactionDetail.TransactionType = 'Credit' then (Set_ContainerTransportationandUnloading.TotalTransAmount) else 0 end As Credit, 0 As InstrumentNo, GL_TransactionHeader.Narration As Comments, GL_codecombinationDetail.CodeCombinationID as SupplierAccountCode, GL_codecombinationDetail.Description as CodeDescription FROM GL_TransactionHeader INNER JOIN GL_TransactionDetail ON GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID AND GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID AND GL_TransactionDetail.PeriodID=GL_TransactionHeader.PeriodID AND GL_TransactionHeader.Status=1 AND GL_TransactionDetail.TransactionType = 'Credit' INNER JOIN Set_ContainerTransportationandUnloading ON Set_ContainerTransportationandUnloading.ContainerTransportationID = GL_TransactionDetail.SourceHeaderID AND GL_TransactionHeader.Status=1 INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = GL_TransactionHeader.CompanyID AND SET_DocumentType.PeriodID = GL_TransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID AND SET_DocumentType.DocumentType='Transportation' INNER JOIN AR_SET_Customer ON Set_ContainerTransportationandUnloading.TransporterID = AR_SET_Customer.CustomerID AND AR_SET_Customer.Status = 1 AND AR_SET_Customer.IsActive = 1
INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID
INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode AND AR_SET_BusinessPartner.BusinessPartnerName='Transporter' inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = AR_SET_BusinessPartnerTypes.FK_CodeCombinationID WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND GL_TransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0}
UNION ALL Select distinct fintab3.DocumentDate, fintab3.DocumentType, fintab3.CostCenterName, fintab3.CustomerID, fintab3.CustomerName, fintab3.DocumentNo, Sum(fintab3.Debit) As Debit, Sum(fintab3.Credit) As Credit, fintab3.InstrumentNo, fintab3.Comments, fintab3.SupplierAccountCode As CodeCombinationID, fintab3.CodeDescription From (
Select Distinct GL_TransactionHeader.DocumentDate, SET_DocumentType.DocumentType, '' as CostCenterName, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName,GL_TransactionHeader.DocumentNo as DocumentNo, Case when GL_TransactionDetail.TransactionType = 'Debit' then ([Fabrics_LoadingAndUnloading].TotalUnloadAmount) else 0 end As Debit, Case when GL_TransactionDetail.TransactionType = 'Credit' then ([Fabrics_LoadingAndUnloading].TotalUnloadAmount) else 0 end As Credit, 0 As InstrumentNo, GL_TransactionHeader.Narration As Comments, GL_codecombinationDetail.CodeCombinationID as SupplierAccountCode, GL_codecombinationDetail.Description as CodeDescription FROM GL_TransactionHeader INNER JOIN GL_TransactionDetail ON GL_TransactionDetail.TransactionID = GL_TransactionHeader.TransactionID AND GL_TransactionDetail.CompanyID = GL_TransactionHeader.CompanyID AND GL_TransactionDetail.PeriodID=GL_TransactionHeader.PeriodID AND GL_TransactionHeader.Status=1 AND GL_TransactionDetail.TransactionType = 'Credit' INNER JOIN [Fabrics_LoadingAndUnloading] ON [Fabrics_LoadingAndUnloading].LoadingUnloadingID = GL_TransactionDetail.SourceHeaderID AND GL_TransactionHeader.Status=1 AND [Fabrics_LoadingAndUnloading].StatusCode=1 INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = GL_TransactionHeader.CompanyID AND SET_DocumentType.PeriodID = GL_TransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID AND SET_DocumentType.DocumentType like '%Loading%' INNER JOIN AR_SET_Customer ON [Fabrics_LoadingAndUnloading].ContractorID = AR_SET_Customer.CustomerID
AND AR_SET_Customer.Status = 1 AND AR_SET_Customer.IsActive = 1
INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = AR_SET_BusinessPartnerTypes.FK_CodeCombinationID
INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode AND (AR_SET_BusinessPartner.BusinessPartnerName='Loading_Contractor/Unloading_Contractor') WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND GL_TransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate
and (GL_codecombinationDetail.CodeCombinationID = @AccountCode OR @AccountCode is null) {0}
) as fintab3 Group By fintab3.DocumentDate, fintab3.DocumentType, fintab3.CostCenterName, fintab3.CustomerID, fintab3.CustomerName, fintab3.DocumentNo, fintab3.InstrumentNo, fintab3.Comments, fintab3.SupplierAccountCode, fintab3.CodeDescription

select FinalTAB.CustomerID, FinalTAB.Name as CustomerName,FinalTAB.codeCombinationID,SUM( CASE WHEN DocumentType not like '%Opening%' then ( CASE WHEN Amount < 0 then abs(FinalTAB.Amount) else 0 end ) else 0 END) as ActivityCredit, SUM(CASE WHEN DocumentType not like '%Opening%' then ( CASE WHEN Amount > 0 then FinalTAB.Amount else 0 end ) else 0 END) as ActivityDebit ,SUM( CASE WHEN DocumentType like '%Opening%' then ( CASE WHEN Amount < 0 then abs(FinalTAB.Amount) else 0 end ) else 0 END) as OpeningCredit, SUM(CASE WHEN DocumentType like '%Opening%' then ( CASE WHEN Amount > 0 then FinalTAB.Amount else 0 end ) else 0 END) as OpeningDebit, abs(sum(isnull( CASE WHEN Amount < 0 then abs(FinalTAB.Amount) else 0 end , 0))) ClosingCredit, sum(isnull( CASE WHEN Amount > 0 then abs(FinalTAB.Amount) else 0 end , 0)) ClosingDebit ,abs(sum(isnull( FinalTAB.Amount,0))) as ClosingAmount , case when sum(isnull( FinalTAB.Amount,0)) < 0 then 'Credit' when sum(isnull( FinalTAB.Amount,0)) > 0 then 'Debit' end as ClosingAmountType from ( select 'Opening' AS DocumentType, @FromDate AS CreateDate, TABopening.CustomerID, TABopening.Name, -1 AS SourceID, SUM(TABopening.Amount) as Amount, '' AS InstrumentNo, '' Comments, '' AS InvoiceNumbers, '' AS InvoiceDocumentNo, '' AS DocumentNo, @FromDate AS DocumentDate, 0 AS FreightAmount, 0 AS ForAlhajAmount , TABopening.StatusCode,TABopening.codeCombinationID from ( SELECT FINTAB.DocumentType, Fintab.CreateDate, FINTAB.CustomerID, FINTAB.Name, FinTab.SourceID, SUM(FINTAB.Amount) as Amount, FINTAB.InstrumentNo, FINTAB.Comments, FINTAB.InvoiceNumbers, FINTAB.InvoiceDocumentNo, FINTAB.DocumentNo, FINTAB.DocumentDate, FINTAB.FreightAmount, FINTAB.ForAlhajAmount , FINTAB.StatusCode,FINTAB.CodeCombinationID FROM ( Select 'Opening' as DocumentType, @FromDate AS CreateDate, openingTAB.CustomerID, openingTAB.Name, -1 AS SourceID, sum(openingTAB.Amount) as Amount, '' as InstrumentNo, '' as Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, '' as DocumentNo, @FromDate as DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount , openingTAB.StatusCode,openingTAB.FK_CodeCombinationID as CodeCombinationID From ( ---------- OPENING BALANCE VENDOR INVOICE ---------- SELECT 0 as Amount, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS Name, AR_ReceiptCustomerDetail.ReceiptCustomerID as SourceID ,AR_ReceiptTransactionHeader.StatusCode ,AR_SET_BusinessPartnerTypes.FK_CodeCombinationID FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 --AND AR_ReceiptTransactionHeader.StatusCode = 1 INNER JOIN AR_ReceiptCustomerDetail on AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and AR_ReceiptCustomerDetail.Status = 1 INNER JOIN AR_SET_Customer ON AR_ReceiptCustomerDetail.CustomerID = AR_SET_Customer.CustomerID AND AR_ReceiptCustomerDetail.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptCustomerDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 --AND AR_SET_Customer.IsActive = 1 INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptCustomerDetail.BusinessPartnerTypeID AND (AR_SET_BusinessPartnerTypes.FK_CodeCombinationID=@AccountCode OR @AccountCode is null) ---Chart of AccountCode Filter INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode LEFT Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID AND AR_ReceiptAccountsDetail.Status = 1 {6} WHERE AR_SET_Customer.CompanyID = @CompanyID AND AR_SET_Customer.PeriodID = @PeriodID AND convert(date,AR_ReceiptTransactionHeader.DocumentDate) < @FromDate And SET_DocumentType.status = 1 {3} GROUP BY AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptCustomerDetail.TransactionType, AR_ReceiptCustomerDetail.ReceiptCustomerID,AR_ReceiptTransactionHeader.StatusCode ,AR_SET_BusinessPartnerTypes.FK_CodeCombinationID ) OpeningTAB GROUP BY OpeningTAB.CustomerID ,OpeningTAB.Name,OpeningTAB.StatusCode,OpeningTAB.FK_CodeCombinationID
UNION ALL
select distinct TABInvoice.DocumentType, TABInvoice.CreateDate, TABInvoice.CustomerID, TABInvoice.BusinessPartnerName, TABInvoice.SourceID, TABInvoice.Amount, TABInvoice.InstrumentNo, TABInvoice.Comments, TABInvoice.InvoiceNumbers, TABInvoice.InvoiceDocumentNo, TABInvoice.DocumentNo, TABInvoice.DocumentDate, TABInvoice.FreightAmount, TABInvoice.ForAlhajAmount ,TABInvoice.StatusCode,TABInvoice.CodeCombinationID from ( ---------- Vendor Invoice ---------- SELECT distinct AR_InvoiceHeader.companyID, Set_DocumentType.TransactionType, case when AR_SET_BusinessPartnerTypes.TypeCode is null then ( select top 1 CUS.TypeCode from AR_SET_BusinessPartnerTypes CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.BusinessPartnerID AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID and AR_InvoiceSupplierDetail.BusinessPartnerTypeID = CUS.TypeCode And AR_InvoiceSupplierDetail.Status = 1
) else AR_SET_BusinessPartnerTypes.TypeCode end as TypeCode,
case when AR_InvoiceHeader.vendorID is null then ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID And AR_InvoiceSupplierDetail.Status = 1 And CUS.Status= 1 ) else ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceHeader.vendorID = CUS.CustomerID AND AR_InvoiceHeader.CompanyID = CUS.CompanyID AND AR_InvoiceHeader.PeriodID = CUS.PeriodID And AR_InvoiceHeader.Status= 1 And CUS.Status= 1 ) end as CustomerID, SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate, case when AR_InvoiceHeader.vendorID is null then ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID And AR_InvoiceSupplierDetail.Status= 1 And CUS.Status= 1 ) else ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceHeader.vendorID = CUS.CustomerID AND AR_InvoiceHeader.CompanyID = CUS.CompanyID AND AR_InvoiceHeader.PeriodID = CUS.PeriodID And AR_InvoiceHeader.Status= 1 And CUS.Status= 1 ) end as BusinessPartnerName, AR_InvoiceSupplierDetail.InvoiceSupplierID as SourceID, case when AR_InvoiceHeader.vendorID is null then (Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount else AR_InvoiceSupplierDetail.Amount * -1 end) else ( Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceHeader.AmountPaid when SET_DocumentType.DocumentType = 'Debit Note' then AR_InvoiceHeader.AmountPaid else (AR_InvoiceHeader.AmountPaid+AR_InvoiceHeader.FreightAmount - isnull(AR_InvoiceHeader.OtherAmount,0)) * -1 end ) end as Amount, '0' AS InstrumentNo, AR_InvoiceHeader.Description AS Comments, AR_InvoiceHeader.VendorReferenceNumber as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, AR_InvoiceHeader.InvoiceDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_InvoiceHeader.StatusCode , case when AR_SET_BusinessPartnerTypes.TypeCode is null then ( select top 1 CUS.FK_CodeCombinationID from AR_SET_BusinessPartnerTypes CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.BusinessPartnerID AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID and AR_InvoiceSupplierDetail.BusinessPartnerTypeID = CUS.TypeCode And AR_InvoiceSupplierDetail.Status = 1
) else AR_SET_BusinessPartnerTypes.FK_CodeCombinationID end as CodeCombinationID FROM SET_DocumentType INNER JOIN AR_InvoiceHeader ON SET_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_InvoiceHeader.InvoiceType AND AR_InvoiceHeader.Status = 1 --AND AR_InvoiceHeader.StatusCode = 1 LEFT JOIN AR_InvoiceDetail on AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceDetail.Status = 1 LEFT JOIN AR_InvoiceSupplierDetail on AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceSupplierDetail.Status = 1 LEFT JOIN AR_SET_Customer ASCUS ON AR_InvoiceSupplierDetail.SupplierID = ASCUS.CustomerID AND AR_InvoiceSupplierDetail.CompanyID = ASCUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = ASCUS.PeriodID AND ASCUS.Status = 1 left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.vENDORid AND AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID AND (AR_SET_BusinessPartnerTypes.FK_CodeCombinationID=@AccountCode OR @AccountCode is null) ---Chart of AccountCode Filter
LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode {6} WHERE AR_InvoiceHeader.CompanyID = @companyId AND AR_InvoiceHeader.PeriodID = @PeriodId AND convert(date,AR_InvoiceHeader.InvoiceDate) < @FromDate And SET_DocumentType.Status = 1 {4} --and SET_DocumentType.documenttype not like '%Opening%' ) TABInvoice where TABInvoice.companyID = @companyId AND (TABInvoice.CodeCombinationID=@AccountCode OR @AccountCode is null) {7} {8}
---------------------Vendor INvoice Supplier Detail
union ALL
select distinct TABInvoice.DocumentType, TABInvoice.CreateDate, TABInvoice.CustomerID, TABInvoice.BusinessPartnerName, TABInvoice.SourceID, TABInvoice.Amount, TABInvoice.InstrumentNo, TABInvoice.Comments, TABInvoice.InvoiceNumbers, TABInvoice.InvoiceDocumentNo, TABInvoice.DocumentNo, TABInvoice.DocumentDate, TABInvoice.FreightAmount, TABInvoice.ForAlhajAmount ,TABInvoice.StatusCode,TABInvoice.CodeCombinationID from ( ---------- Vendor Invoice ---------- SELECT distinct AR_InvoiceHeader.companyID, Set_DocumentType.TransactionType, case when AR_SET_BusinessPartnerTypes.TypeCode is null then ( select top 1 CUS.TypeCode from AR_SET_BusinessPartnerTypes CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.BusinessPartnerID AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID and AR_InvoiceSupplierDetail.BusinessPartnerTypeID = CUS.TypeCode And AR_InvoiceSupplierDetail.Status = 1
) else AR_SET_BusinessPartnerTypes.TypeCode end as TypeCode, ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID And AR_InvoiceSupplierDetail.Status= 1 And CUS.Status= 1 ) as CustomerID, SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate, ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID And AR_InvoiceSupplierDetail.Status= 1 And CUS.Status= 1 ) BusinessPartnerName, AR_InvoiceSupplierDetail.InvoiceSupplierID as SourceID, Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount else AR_InvoiceSupplierDetail.Amount * -1 end as Amount, '0' AS InstrumentNo, AR_InvoiceSupplierDetail.Narration AS Comments, AR_InvoiceHeader.VendorReferenceNumber as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, AR_InvoiceHeader.InvoiceDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_InvoiceHeader.StatusCode , case when AR_SET_BusinessPartnerTypes.TypeCode is null then ( select top 1 CUS.FK_CodeCombinationID from AR_SET_BusinessPartnerTypes CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.BusinessPartnerID AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID and AR_InvoiceSupplierDetail.BusinessPartnerTypeID = CUS.TypeCode And AR_InvoiceSupplierDetail.Status = 1
) else AR_SET_BusinessPartnerTypes.FK_CodeCombinationID end as CodeCombinationID FROM SET_DocumentType INNER JOIN AR_InvoiceHeader ON SET_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_InvoiceHeader.InvoiceType AND AR_InvoiceHeader.Status = 1 --AND AR_InvoiceHeader.StatusCode = 1 Inner JOIN AR_InvoiceDetail on AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceDetail.Status = 1 Inner JOIN AR_InvoiceSupplierDetail on AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceSupplierDetail.Status = 1 Inner JOIN AR_SET_Customer ASCUS ON AR_InvoiceSupplierDetail.SupplierID = ASCUS.CustomerID AND AR_InvoiceSupplierDetail.CompanyID = ASCUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = ASCUS.PeriodID AND ASCUS.Status = 1 inner JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceSupplierDetail.SupplierID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceSupplierDetail.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceSupplierDetail.PeriodID AND (AR_SET_BusinessPartnerTypes.FK_CodeCombinationID=@AccountCode OR @AccountCode is null) ------------Chart of AccountCode Paramater inner JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_InvoiceSupplierDetail.BusinessPartnerTypeID {6} WHERE AR_InvoiceHeader.CompanyID = @companyId AND AR_InvoiceHeader.PeriodID = @PeriodId AND convert(date,AR_InvoiceHeader.InvoiceDate) < @FromDate And SET_DocumentType.Status = 1 {4} --and SET_DocumentType.documenttype not like '%Opening%' ) TABInvoice where TABInvoice.companyID = @companyId {7}
---------------------------------------------------
UNION ALL ---------- Payment ---------- SELECT SET_DocumentType.DocumentType, AP_PaymentHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AP_PaymentHeader.PaymentID as SourceID, (Case AP_PaymentSupplierDetail.TransactionType when 'Debit' then AP_PaymentSupplierDetail.Amount else AP_PaymentSupplierDetail.Amount * -1 end) as Amount, AP_PaymentHeader.PaymentServerOrderNo AS InstrumentNo, IsNull(AP_PaymentHeader.Comments, '') + (Case When AP_PaymentHeader.ReversalComments IS NULL Then '' Else ' ' + AP_PaymentHeader.ReversalComments End) AS Comments, case when AP_PaymentHeader.POHeaderID is null then (ISNULL( ( SELECT STUFF( ( SELECT AR_InvoiceHeader.InvoiceNumber FROM AP_PaymentHeader childPayment LEFT JOIN AP_PaymentInvoicesDetail ON AP_PaymentInvoicesDetail.PaymentHeaderID = childPayment.PaymentID AND AP_PaymentInvoicesDetail.CompanyID = childPayment.CompanyID AND AP_PaymentInvoicesDetail.PeriodID = childPayment.PeriodID AND AP_PaymentInvoicesDetail.Status = 1 LEFT JOIN AR_InvoiceHeader ON AR_InvoiceHeader.InvoiceID = AP_PaymentInvoicesDetail.InvoiceHeaderID AND AR_InvoiceHeader.CompanyID = AP_PaymentInvoicesDetail.CompanyID AND AR_InvoiceHeader.PeriodID = AP_PaymentInvoicesDetail.PeriodID AND AR_InvoiceHeader.Status = 1 LEFT JOIN AR_InvoiceDetail ON AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID AND AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID AND AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID AND AR_InvoiceDetail.Status = 1 where childPayment.PaymentID = payment.PaymentID and childPayment.CompanyID = payment.CompanyID and childPayment.PeriodID = payment.PeriodID And childPayment.Status = 1 ORDER BY AR_InvoiceHeader.InvoiceNumber FOR XML PATH(''), TYPE ).value('.', 'varchar(max)'), 1, 2, '') AS InvoiceNumbers FROM AP_PaymentHeader payment where payment.PaymentID = AP_PaymentHeader.PaymentID and payment.CompanyID = AP_PaymentHeader.CompanyID and payment.PeriodID = AP_PaymentHeader.PeriodID And Payment.Status = 1 ), '')) else (Select DocumentNumber from AP_PurchaseOrderHeader where AP_PurchaseOrderHeader.POHeaderID = AP_PaymentHeader.POHeaderID and AP_PurchaseOrderHeader.CompanyID = AP_PaymentHeader.CompanyID and AP_PurchaseOrderHeader.PeriodID = AP_PaymentHeader.PeriodID ) end as InvoiceNumbers, ISNULL( ( SELECT STUFF( ( SELECT ', ' + AP_PaymentDetail.InvoiceDocumentNo FROM AP_PaymentDetail WHERE payment1.PaymentID = AP_PaymentDetail.PaymentHeaderID And AP_PaymentDetail.Status = 1 ORDER BY AP_PaymentDetail.InvoiceDocumentNo FOR XML PATH(''), TYPE ).value('.', 'varchar(max)'), 1, 2, '') AS InvoiceDocumentNo FROM AP_PaymentHeader payment1 where payment1.PaymentID = AP_PaymentHeader.PaymentID and payment1.CompanyID = AP_PaymentHeader.CompanyID and payment1.PeriodID = AP_PaymentHeader.PeriodID ), '') as InvoiceDocumentNo, ISNULL(AP_PaymentHeader.DocumentNo, 0) AS DocumentNo, AP_PaymentHeader.DocumentDate AS DocumentDate, 0 AS FreightAmount , IsNull(AP_Payment_AccountsDetail.Amount, 0) * -1 As ForAlhajAmount ,AP_PaymentHeader.StatusCode ,AR_SET_BusinessPartnerTypes.FK_CodeCombinationID as CodeCombinationID FROM SET_DocumentType INNER JOIN AP_PaymentHeader ON SET_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND SET_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND AP_PaymentHeader.Status = 1 --AND AP_PaymentHeader.StatusCode = 1 INNER Join AP_PaymentSupplierDetail on AP_PaymentSupplierDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentSupplierDetail.CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentSupplierDetail.PeriodID = AP_PaymentHeader.PeriodID and AP_PaymentSupplierDetail.Status = 1 INNER JOIN AR_SET_Customer ON AP_PaymentSupplierDetail.SupplierID = AR_SET_Customer.CustomerID AND AP_PaymentSupplierDetail.CompanyID = AR_SET_Customer.CompanyID AND AP_PaymentSupplierDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 -- AND AR_SET_Customer.IsActive = 1 left join AP_Payment_AccountsDetail on AP_Payment_AccountsDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_Payment_AccountsDetail.IsBP <> 0 and AP_Payment_AccountsDetail.TransactionType = 'Credit' and AP_Payment_AccountsDetail.Status = 1 INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID and AR_SET_BusinessPartnerTypes.TypeCode = AP_PaymentSupplierDetail.BusinessPartnerTypeID AND (AR_SET_BusinessPartnerTypes.FK_CodeCombinationID=@AccountCode OR @AccountCode is null) ------------Chart of AccountCode Paramater --------------------------------------------------------------------------------------------------- WHERE AP_PaymentHeader.CompanyID = @CompanyId AND AP_PaymentHeader.PeriodID = @PeriodId AND convert(date,AP_PaymentHeader.DocumentDate) < @FromDate {0} {1} {5} GROUP BY AP_PaymentHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AP_PaymentSupplierDetail.PaymentSupplierID, AP_PaymentSupplierDetail.TransactionType, AP_PaymentSupplierDetail.Amount, AP_PaymentHeader.DocumentNo, AP_PaymentHeader.DocumentDate, SET_DocumentType.DocumentType, AP_PaymentHeader.PaymentID, AP_PaymentHeader.CompanyID, AP_PaymentHeader.PeriodID, AP_PaymentHeader.Comments, AP_PaymentHeader.POHeaderID, AP_PaymentHeader.PaymentServerOrderNo, AP_Payment_AccountsDetail.Amount, AP_PaymentHeader.ReversalComments ,AP_PaymentHeader.StatusCode,AR_SET_BusinessPartnerTypes.FK_CodeCombinationID UNION ALL
-- PAYMENT -- SINGLE BUSINESS PARTNER CASE SELECT SET_DocumentType.DocumentType, AP_PaymentHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AP_PaymentHeader.PaymentID as SourceID, (Case when AP_PaymentHeader.CustomerTransactionType is not null then AP_PaymentHeader.Amount * -1 else AP_PaymentHeader.Amount end) as Amount, AP_PaymentHeader.PaymentServerOrderNo AS InstrumentNo, AP_PaymentHeader.Comments + (Case When AP_PaymentHeader.ReversalComments IS NULL Then '' Else ' ' + AP_PaymentHeader.ReversalComments End) AS Comments, case when AP_PaymentHeader.POHeaderID is null then (ISNULL( ( SELECT STUFF( ( SELECT distinct AR_InvoiceHeader.InvoiceNumber FROM AP_PaymentHeader childPayment LEFT JOIN AP_PaymentInvoicesDetail ON AP_PaymentInvoicesDetail.PaymentHeaderID = childPayment.PaymentID AND AP_PaymentInvoicesDetail.CompanyID = childPayment.CompanyID AND AP_PaymentInvoicesDetail.PeriodID = childPayment.PeriodID AND AP_PaymentInvoicesDetail.Status = 1 LEFT JOIN AR_InvoiceHeader ON AR_InvoiceHeader.InvoiceID = AP_PaymentInvoicesDetail.InvoiceHeaderID AND AR_InvoiceHeader.CompanyID = AP_PaymentInvoicesDetail.CompanyID AND AR_InvoiceHeader.PeriodID = AP_PaymentInvoicesDetail.PeriodID AND AR_InvoiceHeader.Status = 1 LEFT JOIN AR_InvoiceDetail ON AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID AND AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID AND AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID AND AR_InvoiceDetail.Status = 1 where childPayment.PaymentID = payment.PaymentID and childPayment.CompanyID = payment.CompanyID and childPayment.PeriodID = payment.PeriodID And childPayment.Status = 1 ORDER BY AR_InvoiceHeader.InvoiceNumber FOR XML PATH(''), TYPE ).value('.', 'varchar(max)'), 1, 0, '') AS InvoiceNumbers FROM AP_PaymentHeader payment where payment.PaymentID = AP_PaymentHeader.PaymentID and payment.CompanyID = AP_PaymentHeader.CompanyID and payment.PeriodID = AP_PaymentHeader.PeriodID and payment.status = 1
), '')) else (Select DocumentNumber from AP_PurchaseOrderHeader where AP_PurchaseOrderHeader.POHeaderID = AP_PaymentHeader.POHeaderID and AP_PurchaseOrderHeader.CompanyID = AP_PaymentHeader.CompanyID and AP_PurchaseOrderHeader.PeriodID = AP_PaymentHeader.PeriodID ) end as InvoiceNumbers, ISNULL( ( SELECT STUFF( ( SELECT ', ' + AP_PaymentDetail.InvoiceDocumentNo FROM AP_PaymentDetail WHERE payment1.PaymentID = AP_PaymentDetail.PaymentHeaderID And AP_PaymentDetail.status = 1 ORDER BY AP_PaymentDetail.InvoiceDocumentNo FOR XML PATH(''), TYPE ).value('.', 'varchar(max)'), 1, 2, '') AS InvoiceDocumentNo FROM AP_PaymentHeader payment1 where payment1.PaymentID = AP_PaymentHeader.PaymentID and payment1.CompanyID = AP_PaymentHeader.CompanyID and payment1.PeriodID = AP_PaymentHeader.PeriodID And payment1.Status = 1 ), '') as InvoiceDocumentNo, ISNULL(AP_PaymentHeader.DocumentNo, 0) AS DocumentNo, AP_PaymentHeader.DocumentDate AS DocumentDate, 0 AS FreightAmount , IsNull(AP_Payment_AccountsDetail.Amount, 0) * -1 As ForAlhajAmount ,AP_PaymentHeader.StatusCode ,AR_SET_BusinessPartnerTypes.FK_CodeCombinationID as CodeCombinationID FROM SET_DocumentType INNER JOIN AP_PaymentHeader ON SET_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND SET_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND AP_PaymentHeader.Status = 1 --AND AP_PaymentHeader.StatusCode = 1 INNER JOIN AR_SET_Customer ON AP_PaymentHeader.VendorID = AR_SET_Customer.CustomerID AND AP_PaymentHeader.CompanyID = AR_SET_Customer.CompanyID AND AP_PaymentHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 -- AND AR_SET_Customer.IsActive = 1 INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND (AR_SET_BusinessPartnerTypes.FK_CodeCombinationID=@AccountCode OR @AccountCode is null) ------------Chart of AccountCode Paramater INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode
left join AP_Payment_AccountsDetail on AP_Payment_AccountsDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_Payment_AccountsDetail.IsBP <> 0 and AP_Payment_AccountsDetail.TransactionType = 'Credit' and AP_Payment_AccountsDetail.Status = 1 {6} WHERE AP_PaymentHeader.CompanyID = @CompanyId AND AP_PaymentHeader.PeriodID = @PeriodId AND convert(date,AP_PaymentHeader.DocumentDate) < @FromDate And SET_DocumentType.Status = 1 {0} {1} {5} GROUP BY AP_PaymentHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AP_PaymentHeader.CustomerTransactionType, AP_PaymentHeader.Amount, AP_PaymentHeader.DocumentNo, AP_PaymentHeader.DocumentDat
